// ACP认证刷题 - 完整题目数据 (共160题)
// 自动生成，请勿手动修改
// 每个模块20题，共8个模块

const QUESTIONS = [
  {id:'ecs01',module:'云服务器ECS',type:'single',question:"阿里云 ECS 实例的自定义镜像是基于什么创建的？",options:["基于某个 ECS 实例的系统盘","基于 OSS 中的文件","基于快照","基于 RDS 数据库"],answer:[0],explanation:"自定义镜像是基于某个已有 ECS 实例的系统盘创建的，包含了该实例的操作系统环境和预装软件，可用于快速创建新实例。",ref:'help.aliyun.com/zh/ecs/'},
  {id:'ecs02',module:'云服务器ECS',type:'single',question:"ECS 安全组的规则中，\"授权策略\"不包含以下哪项？",options:["允许","拒绝","全部","优先级"],answer:[2],explanation:"安全组规则的授权策略包含\"允许\"和\"拒绝\"两种，没有\"全部\"选项。\"优先级\"是规则的一个属性而非授权策略。",ref:'help.aliyun.com/zh/ecs/'},
  {id:'ecs03',module:'云服务器ECS',type:'multi',question:"关于 ECS 磁盘类型，以下说法正确的有哪些？",options:["ESSD 是增强型 SSD 云盘","SSD 云盘适合高随机读写场景","高效云盘的性能介于 SSD 和普通云盘之间","普通云盘适合对性能要求极高的核心数据库"],answer:[0,1,2],explanation:"ESSD（增强型 SSD）是阿里云新一代超高性能云盘；SSD 云盘适合高随机 I/O 场景；高效云盘性能居中。普通云盘性能较低，不适合核心数据库等高性能需求场景。",ref:'help.aliyun.com/zh/ecs/'},
  {id:'ecs04',module:'云服务器ECS',type:'judge',question:"ECS 快照是磁盘数据在某一个时间点的记录，可用于磁盘数据恢复。",options:["正确","错误"],answer:[0],explanation:"快照是磁盘数据在某一时刻的状态记录，可用于恢复磁盘数据、创建自定义镜像或数据迁移。",ref:'help.aliyun.com/zh/ecs/'},
  {id:'ecs05',module:'云服务器ECS',type:'single',question:"ECS 实例规格中，\"ecs.g6.large\" 的 \"g\" 代表什么系列？",options:["计算型","通用型","内存型","GPU 型"],answer:[1],explanation:"阿里云 ECS 规格族命名中，g 代表通用型（General Purpose），c 代表计算型，r 代表内存型，gn 代表 GPU 型。",ref:'help.aliyun.com/zh/ecs/'},
  {id:'ecs06',module:'云服务器ECS',type:'judge',question:"一台 ECS 实例可以同时挂载多块云盘，但系统盘只能有一块。",options:["正确","错误"],answer:[0],explanation:"ECS 实例只能有一块系统盘，但可以挂载多块数据盘，数据盘和系统盘的容量和性能可独立配置。",ref:'help.aliyun.com/zh/ecs/'},
  {id:'ecs07',module:'云服务器ECS',type:'multi',question:"以下哪些是 ECS 实例的常见计费方式？",options:["按量付费","包年包月","抢占式实例","按 CPU 使用率计费"],answer:[0,1,2],explanation:"ECS 支持按量付费、包年包月和抢占式实例三种计费方式。没有\"按 CPU 使用率计费\"这种模式。",ref:'help.aliyun.com/zh/ecs/'},
  {id:'ecs08',module:'云服务器ECS',type:'single',question:"ECS 实例的\"实例规格\"主要决定什么？",options:["CPU 核数和内存大小","磁盘容量","公网带宽","安全组规则"],answer:[0],explanation:"实例规格决定了 ECS 实例的 CPU 核数和内存大小。磁盘容量、公网带宽和安全组规则是独立配置的。",ref:'help.aliyun.com/zh/ecs/'},
  {id:'ecs09',module:'云服务器ECS',type:'single',question:"关于阿里云ECS实例启动模板（Launch Template），以下说法正确的是？",options:["实例启动模板仅支持创建一个版本，不支持多版本管理","实例启动模板支持创建多个版本，每个版本可包含不同的实例配置参数，创建实例时可指定版本","实例启动模板创建后可以随时修改已有版本的配置参数","实例启动模板不支持与弹性伸缩（Auto Scaling）配合使用"],answer:[1],explanation:"实例启动模板支持多版本管理，每个版本可以包含实例规格、镜像、网络、安全组等配置参数，创建实例时可指定模板版本快速创建。已有版本创建后不可修改，但可基于已有版本创建新版本。实例启动模板可以与弹性伸缩配合使用，在伸缩组中通过指定启动模板来创建实例。",ref:'help.aliyun.com/zh/ecs/user-guide/实例启动模板/'},
  {id:'ecs10',module:'云服务器ECS',type:'single',question:"关于阿里云镜像市场，以下说法正确的是？",options:["镜像市场仅提供阿里云官方制作的公共镜像，不提供第三方镜像","镜像市场的所有镜像均为免费提供，不收取任何额外费用","镜像市场提供第三方ISV服务商提供的镜像，部分镜像需付费使用，费用通常包含软件许可费","使用镜像市场镜像创建ECS实例后，无法再更换为其他镜像"],answer:[2],explanation:"阿里云镜像市场不仅提供官方公共镜像，还提供第三方独立软件供应商（ISV）提供的镜像，涵盖各种操作系统环境和应用场景。部分镜像需付费使用，费用通常包含软件许可费，按小时或包年包月计费。使用镜像市场镜像创建实例后，仍可通过更换系统盘的方式更换为其他镜像。",ref:'help.aliyun.com/zh/ecs/user-guide/镜像/镜像市场/'},
  {id:'ecs11',module:'云服务器ECS',type:'single',question:"当ECS实例所在底层物理服务器发生故障时，关于ECS实例自动恢复（实例迁移）机制，以下说法正确的是？",options:["系统会将实例自动迁移到健康的物理服务器上，实例ID、私有IP和系统盘数据保持不变","实例恢复功能需要用户在控制台手动触发，系统不会自动执行","实例恢复后公网IP一定会变化，需要重新配置","实例恢复功能仅适用于包年包月实例，按量付费实例不支持自动恢复"],answer:[0],explanation:"当底层物理服务器发生故障时，阿里云会自动将ECS实例迁移到健康的物理服务器上恢复运行。迁移后实例ID、私有IP地址、系统盘数据等保持不变。如果实例使用弹性公网IP（EIP），公网IP也保持不变；若使用固定公网IP则可能变化。该功能对包年包月和按量付费实例均适用，由系统自动执行，无需用户干预。",ref:'help.aliyun.com/zh/ecs/user-guide/实例/实例自动恢复/'},
  {id:'ecs12',module:'云服务器ECS',type:'multi',question:"关于阿里云专有宿主机DDH（Dedicated Host），以下说法正确的有哪些？",options:["DDH是专供单个租户使用的物理服务器，可满足合规监管和许可证管理要求","DDH上的ECS实例可以迁移到同一账号下的其他DDH或共享宿主机上","DDH支持自动部署功能，创建实例时系统自动选择有足够资源的DDH","DDH上的CPU、内存等物理资源由多个租户共享使用"],answer:[0,1,2],explanation:"专有宿主机DDH是专供单个租户使用的物理服务器，物理资源不会被其他租户共享，可满足合规监管要求（如等保合规）和自带许可证（BYOL）管理需求。DDH上的实例可以在同一账号下的不同DDH间迁移，也可以从DDH迁移到共享宿主机。创建实例时支持自动部署，系统自动选择资源充足的DDH，也支持手动指定DDH。选项D错误，DDH的资源是独享的，不存在多租户共享。",ref:'help.aliyun.com/zh/ecs/user-guide/专有宿主机/'},
  {id:'ecs13',module:'云服务器ECS',type:'single',question:"关于阿里云预留实例券（Reserved Instance），以下说法正确的是？",options:["预留实例券是一种实物计算资源，购买后立即创建并分配ECS实例","预留实例券用于抵扣按量付费ECS实例的账单，享受比按量付费更优惠的价格，本身不创建实例","预留实例券仅能用于抵扣包年包月实例的费用","预留实例券购买后无法退订，也不支持区域和可用区的灵活调整"],answer:[1],explanation:"预留实例券是一种账单抵扣凭证，购买后用于抵消匹配的按量付费ECS实例的计算资源（vCPU和内存）费用，享受比按量付费更低的优惠价格。预留实例券本身不会创建实例，需用户自行创建匹配规格的按量付费实例才能享受抵扣。预留实例券分为区域级和可用区级，区域级支持灵活匹配可用区。预留实例券支持退订（需满足退订条件）。",ref:'help.aliyun.com/zh/ecs/user-guide/预留实例券/'},
  {id:'ecs14',module:'云服务器ECS',type:'judge',question:"阿里云ECS标签可以绑定到实例、云盘、弹性网卡、快照、镜像和安全组等多种资源上，每个资源最多可绑定20个标签，且支持通过标签控制台进行统一管理和批量编辑。",options:["正确","错误"],answer:[0],explanation:"ECS标签是一种用于资源分类管理的工具，支持绑定到实例、云盘、弹性网卡、快照、镜像、安全组等多种资源类型。每个资源最多可绑定20个标签（标签为键值对形式）。标签可通过标签控制台进行统一管理、搜索和批量编辑，也支持通过API和CLI操作。标签还可与访问控制RAM结合，实现基于标签的权限管理。",ref:'help.aliyun.com/zh/ecs/user-guide/标签/'},
  {id:'ecs15',module:'云服务器ECS',type:'single',question:"关于阿里云ECS云助手，以下说法正确的是？",options:["云助手需要用户在ECS实例中手动安装客户端代理才能使用","云助手仅支持Linux操作系统，不支持Windows系统","云助手支持免登录批量执行Shell或PowerShell命令和发送文件，无需通过SSH或RDP连接实例","云助手命令执行后不支持查看输出结果，仅返回成功或失败状态"],answer:[2],explanation:"云助手是ECS提供的自动化运维工具，阿里云公共镜像默认预装云助手客户端，无需用户手动安装。云助手同时支持Linux和Windows操作系统，Linux执行Shell命令，Windows执行PowerShell命令。用户无需通过SSH或RDP登录实例即可批量执行命令、发送文件，且可查看命令执行的详细输出结果。云助手还支持定时任务和参数化命令。",ref:'help.aliyun.com/zh/ecs/user-guide/云助手/'},
  {id:'ecs16',module:'云服务器ECS',type:'multi',question:"关于ESSD（增强型SSD）云盘的性能级别（Performance Level），以下说法正确的有哪些？",options:["ESSD提供PL0、PL1、PL2、PL3四个性能级别，性能依次递增","PL3级别可提供最高100万IOPS和4000 MB/s的吞吐量，适用于核心数据库等对性能要求极高的场景","ESSD的性能级别支持在线变更，变更后立即生效，无需停机重启实例","不同性能级别的ESSD最低容量要求相同，均为20GB"],answer:[0,1,2],explanation:"ESSD是阿里云推出的超高性能云盘产品，分为PL0、PL1、PL2、PL3四个性能级别，性能依次递增。PL3最高可提供100万IOPS和4000 MB/s吞吐量，适用于核心数据库、SAP HANA等高性能场景。ESSD支持在线变更性能级别，变更后立即生效无需停机。选项D错误，不同性能级别的ESSD最低容量要求不同：PL0最低40GB，PL1最低20GB，PL2最低461GB，PL3最低1261GB。",ref:'help.aliyun.com/zh/ecs/user-guide/块存储/ESSD云盘/'},
  {id:'ecs17',module:'云服务器ECS',type:'single',question:"关于ECS系统盘和数据盘的区别，以下说法正确的是？",options:["系统盘用于存储操作系统，数据盘用于存储用户数据，一个ECS实例最多只能挂载一块数据盘","系统盘在创建实例时自动创建并随实例释放，数据盘可独立创建并灵活挂载到不同实例","系统盘和数据盘只能使用相同的云盘类型，不能分别选择不同类型","系统盘和数据盘都不支持在线扩容，扩容前必须先停止实例"],answer:[1],explanation:"系统盘是创建ECS实例时自动创建的，用于存储操作系统，随实例释放而释放。数据盘用于存储用户数据，可独立创建并灵活挂载和卸载到不同实例。一个ECS实例根据实例规格不同最多可挂载16到17块数据盘。系统盘和数据盘可分别选择不同的云盘类型（如系统盘用ESSD，数据盘用普通云盘）。两者均支持在线扩容（云盘处于使用中状态即可操作），扩容后需在操作系统内部扩展分区和文件系统。",ref:'help.aliyun.com/zh/ecs/user-guide/块存储/云盘概述/'},
  {id:'ecs18',module:'云服务器ECS',type:'judge',question:"按量付费的VPC类型ECS实例在停止时可启用\"停机不收费\"功能，此时实例的vCPU和内存资源不再计费，但系统盘、数据盘等存储资源和固定带宽仍继续计费。经典网络类型的按量付费实例不支持此功能。",options:["正确","错误"],answer:[0],explanation:"\"停机不收费\"是VPC类型按量付费ECS实例的特有功能。启用后停止实例时vCPU和内存资源不再产生费用，但云盘（系统盘和数据盘）的存储费用、固定带宽费用（如果使用按固定带宽计费）仍正常收取。经典网络类型的按量付费实例停止后仍按原标准计费，不支持此功能。此外，如果实例挂载了弹性公网IP，停机期间EIP的费用也继续收取。",ref:'help.aliyun.com/zh/ecs/user-guide/实例/停机不收费/'},
  {id:'ecs19',module:'云服务器ECS',type:'multi',question:"关于阿里云竞价实例和部署集，以下说法正确的有哪些？",options:["竞价实例利用阿里云空闲计算资源，价格通常低于按量付费，但可能因市场价波动或资源库存不足被系统自动回收","竞价实例支持设置实例保护期，在保护期内不会被系统自动回收","部署集可以将ECS实例分散部署在不同的物理服务器上，降低单点硬件故障对业务的影响","部署集仅支持高可用策略，不支持其他部署策略"],answer:[0,1,2],explanation:"竞价实例利用阿里云空闲计算资源，价格随市场供需波动，通常比按量付费优惠。当市场价格高于用户出价或资源库存不足时，实例会被自动回收。竞价实例支持设置保护期（1到6小时），保护期内实例不会被回收。部署集通过将实例分散到不同物理服务器提高业务高可用性。选项D错误，部署集还支持网络低时延策略等多种部署策略。",ref:'help.aliyun.com/zh/ecs/user-guide/竞价实例/'},
  {id:'ecs20',module:'云服务器ECS',type:'judge',question:"SSH密钥对是阿里云ECS提供的一种比密码更安全的实例登录认证方式，同一SSH密钥对可绑定到多台Linux实例。此外，ECS实例元数据可通过访问http://100.100.100.200/latest/meta-data/获取，该接口无需额外认证。",options:["正确","错误"],answer:[0],explanation:"SSH密钥对采用非对称加密算法，比密码登录更安全。同一密钥对可绑定到多台Linux ECS实例，便于统一管理。实例元数据服务通过特殊地址100.100.100.200提供，实例内部可通过HTTP请求获取实例ID、网络配置、实例角色临时凭证等元数据信息，无需额外认证。需注意实例元数据仅能在实例内部访问，外部无法访问该地址。",ref:'help.aliyun.com/zh/ecs/user-guide/SSH密钥对/'},
  {id:'slb01',module:'负载均衡SLB',type:'single',question:"阿里云 SLB 的\"加权轮询\"调度算法中，后端服务器的权重起什么作用？",options:["权重越高的服务器分配到的请求越多","权重越高的服务器响应速度越快","权重越高的服务器优先级越高","权重不影响请求分配"],answer:[0],explanation:"加权轮询（WRR）根据后端服务器配置的权重比例分发请求，权重越高的服务器接收到的请求越多，适用于服务器性能不均的场景。",ref:'help.aliyun.com/zh/slb/'},
  {id:'slb02',module:'负载均衡SLB',type:'multi',question:"阿里云 SLB 支持的调度算法包括哪些？",options:["轮询","加权轮询","加权最小连接数","随机"],answer:[0,1,2],explanation:"SLB 支持三种调度算法：轮询（RR）、加权轮询（WRR）和加权最小连接数（WLC）。不包含\"随机\"算法。",ref:'help.aliyun.com/zh/slb/'},
  {id:'slb03',module:'负载均衡SLB',type:'judge',question:"SLB 健康检查功能会自动移除不健康的后端服务器，待其恢复后自动加回。",options:["正确","错误"],answer:[0],explanation:"SLB 通过健康检查定期检测后端服务器状态，异常的会被自动移除，恢复正常后自动重新加入，保障服务可用性。",ref:'help.aliyun.com/zh/slb/'},
  {id:'slb04',module:'负载均衡SLB',type:'single',question:"SLB 的\"会话保持\"功能主要用于解决什么问题？",options:["保证同一客户端的请求转发到同一后端服务器","保证所有请求均匀分配","保证请求按时间顺序处理","保证请求加密传输"],answer:[0],explanation:"会话保持（Session Stickiness）确保来自同一客户端的后续请求被转发到同一台后端服务器，适用于需要保持登录状态等有状态应用。",ref:'help.aliyun.com/zh/slb/'},
  {id:'slb05',module:'负载均衡SLB',type:'judge',question:"SLB 可以同时接收 TCP 和 HTTP 两种协议的请求。",options:["正确","错误"],answer:[0],explanation:"SLB 支持多种协议监听，包括 TCP、UDP、HTTP 和 HTTPS，可以为同一 SLB 实例配置不同协议的监听规则。",ref:'help.aliyun.com/zh/slb/'},
  {id:'slb06',module:'负载均衡SLB',type:'multi',question:"以下哪些是使用 SLB 的典型场景？",options:["消除单点故障","实现流量分发与负载均衡","提高应用可用性","替代 DNS 解析"],answer:[0,1,2],explanation:"SLB 用于消除单点故障、分发流量、提高可用性。SLB 不能替代 DNS 解析，DNS 和 SLB 在不同层级工作。",ref:'help.aliyun.com/zh/slb/'},
  {id:'slb07',module:'负载均衡SLB',type:'single',question:"关于阿里云传统型负载均衡SLB（CLB）的实例类型，以下说法正确的是？",options:["公网SLB实例仅提供公网IP地址，不支持内网访问","私网SLB实例仅提供私网IP地址，只能在VPC内网中访问，不提供公网IP","公网SLB实例和私网SLB实例都可以直接接收来自互联网的访问请求","私网SLB实例默认分配公网IP，可直接接收互联网请求"],answer:[1],explanation:"SLB实例分为公网和私网两种类型。公网SLB实例提供公网IP地址（可为BGP多线IP），可直接接收来自互联网的访问请求。私网SLB实例仅提供私网IP地址，只能在VPC内网中访问，不能直接接收互联网请求。私网SLB实例如需接收公网请求，可通过绑定EIP的方式实现。",ref:'help.aliyun.com/zh/slb/product-overview/'},
  {id:'slb08',module:'负载均衡SLB',type:'single',question:"在配置SLB监听时，前端端口（监听端口）和后端端口（服务器端口）的关系，以下说法正确的是？",options:["前端端口和后端端口必须相同，不能配置不同的端口号","前端端口和后端端口可以不同，SLB会将前端端口的请求转发到后端服务器的指定端口","一个SLB实例只能配置一个监听，不支持多端口监听","前端端口的范围仅限于80和443两个端口"],answer:[1],explanation:"SLB监听中，前端端口（监听端口）是SLB接收客户端请求的端口，后端端口是SLB将请求转发到后端服务器的端口。两者可以不同，例如前端监听80端口，后端服务器使用8080端口。一个SLB实例支持配置多个监听，每个监听使用不同的前端端口（1到65535），可为每个监听配置不同的后端端口和后端服务器组。前端端口不限于80和443，可使用1到65535范围内的任意端口。",ref:'help.aliyun.com/zh/slb/user-guide/监听/'},
  {id:'slb09',module:'负载均衡SLB',type:'single',question:"关于SLB后端服务器的权重配置，以下说法正确的是？",options:["权重值为0表示该服务器不接收任何新的请求，且正在处理的连接也会被立即断开","权重值越大，分配到该服务器的请求比例越高，权重值范围为0到100","所有后端服务器的权重必须相同，不支持按服务器性能差异设置不同权重","权重配置仅在TCP监听中有效，HTTP和HTTPS监听不支持权重分配"],answer:[1],explanation:"SLB后端服务器权重用于控制请求分配的比例，权重值范围为0到100。权重值越大，分配到的请求越多，可根据服务器性能差异灵活设置不同权重。权重为0时，该服务器不再接收新的请求，但正在处理的连接会继续处理完成（不会被立即断开）。权重配置适用于所有监听协议类型（TCP、UDP、HTTP、HTTPS），不仅限于TCP监听。",ref:'help.aliyun.com/zh/slb/user-guide/后端服务器/'},
  {id:'slb10',module:'负载均衡SLB',type:'multi',question:"关于SLB健康检查，以下说法正确的有哪些？",options:["TCP健康检查通过发起TCP三次握手来检测后端服务器端口是否可用","HTTP健康检查通过发送HTTP请求并检查响应状态码来判断后端服务器的健康状态","健康检查异常的后端服务器会被暂时从负载均衡转发列表中移除，恢复正常后自动重新加入","健康检查的响应超时时间必须大于检查间隔时间，否则健康检查无法正常工作"],answer:[0,1,2],explanation:"SLB健康检查用于检测后端服务器的可用性。TCP健康检查通过TCP三次握手检测端口是否可达；HTTP健康检查通过发送HTTP请求并检查响应状态码（默认2xx和3xx为健康）判断服务状态。健康检查异常的服务器会被暂时移出转发列表，恢复正常后自动重新加入。选项D错误，健康检查的响应超时时间应小于检查间隔时间，而非大于。",ref:'help.aliyun.com/zh/slb/user-guide/健康检查/'},
  {id:'slb11',module:'负载均衡SLB',type:'single',question:"关于SLB的跨可用区容灾能力，以下说法正确的是？",options:["SLB实例只能在单个可用区中创建，不支持跨可用区部署","主备可用区模式的SLB实例在主可用区故障时会自动切换到备可用区，但切换过程可能导致已有连接中断","SLB跨可用区切换是完全无缝的，已有连接不会中断","主备可用区模式中，备可用区的SLB节点在正常运行时也会主动处理流量"],answer:[1],explanation:"阿里云SLB支持主备可用区部署模式，提供跨可用区容灾能力。正常运行时流量由主可用区的SLB节点处理；当主可用区故障时，系统会自动切换到备可用区。切换过程中已有连接可能中断，需要在切换后重新建立连接，因此不是完全无缝的。备可用区的SLB节点在主可用区正常时不主动处理流量，处于待命状态。用户可通过在后端服务器组中配置多可用区的ECS实例实现更完善的高可用架构。",ref:'help.aliyun.com/zh/slb/user-guide/跨可用区容灾/'},
  {id:'slb12',module:'负载均衡SLB',type:'multi',question:"关于传统型负载均衡SLB（CLB）和应用型负载均衡ALB的区别，以下说法正确的有哪些？",options:["CLB主要基于四层转发（也支持七层），ALB专注于七层转发，支持更丰富的HTTP和HTTPS协议功能","ALB支持基于URL路径、HTTP Header、Cookie等的灵活转发规则，CLB的七层转发规则相对简单","CLB和ALB都支持自动弹性伸缩，无需用户选择实例规格即可自动调整处理能力","ALB支持HTTPS监听的证书管理，而CLB不支持HTTPS"],answer:[0,1],explanation:"CLB（传统型SLB）主要基于四层转发，也支持七层转发；ALB专注于七层应用层转发，支持更丰富的HTTP/HTTPS功能。ALB支持基于URL路径、HTTP Header、Cookie等的高级转发规则，CLB的七层转发规则相对简单。选项C错误，CLB性能保障型实例需要用户选择规格，不像ALB那样自动弹性伸缩。选项D错误，CLB同样支持HTTPS监听和证书管理。",ref:'help.aliyun.com/zh/slb/product-overview/'},
  {id:'slb13',module:'负载均衡SLB',type:'judge',question:"SLB实例分为性能保障型和性能共享型。性能保障型实例根据规格提供明确的每秒新建连接数（CPS）和最大并发连接数等性能指标保证；性能共享型实例资源按需共享，不保证性能指标。",options:["正确","错误"],answer:[0],explanation:"SLB实例分为性能保障型和性能共享型。性能保障型实例根据规格（如简约型、标准型、高阶型等）提供明确的性能指标，包括每秒新建连接数（CPS）、最大并发连接数和每秒查询数（QPS）。性能共享型实例的资源由所有用户共享，不保证具体的性能指标，适合对性能要求不高的测试场景。生产环境建议使用性能保障型实例。",ref:'help.aliyun.com/zh/slb/product-overview/实例规格/'},
  {id:'slb14',module:'负载均衡SLB',type:'single',question:"关于SLB的HTTPS监听证书管理，以下说法正确的是？",options:["SLB HTTPS监听只能使用阿里云SSL证书服务中管理的证书，不支持上传第三方证书","SLB支持在负载均衡侧进行SSL/TLS卸载，后端服务器使用HTTP协议接收解密后的流量","一个HTTPS监听只能绑定一个服务器证书，不支持配置多个证书","SLB HTTPS监听不支持SNI（Server Name Indication）功能"],answer:[1],explanation:"SLB的HTTPS监听支持SSL/TLS卸载（SSL Offloading），即由SLB负责SSL加解密，后端服务器使用HTTP协议接收解密后的流量，减轻后端服务器的加解密压力。SLB支持上传第三方证书，也支持使用阿里云SSL证书服务的证书。一个HTTPS监听可绑定默认服务器证书，还支持通过SNI功能为不同域名绑定不同证书。SLB HTTPS监听支持SNI功能，可根据请求域名返回对应证书。",ref:'help.aliyun.com/zh/slb/user-guide/监听/HTTPS监听/'},
  {id:'slb15',module:'负载均衡SLB',type:'multi',question:"关于SLB访问控制策略组（ACL），以下说法正确的有哪些？",options:["访问控制策略组可配置白名单和黑名单两种类型，白名单仅允许指定IP访问，黑名单拒绝指定IP访问","一个监听可以同时绑定白名单策略组和黑名单策略组","访问控制策略组支持添加单个IP地址和CIDR网段格式的IP条目","访问控制策略组修改后实时生效，无需重启SLB实例"],answer:[0,2,3],explanation:"SLB访问控制策略组（ACL）支持白名单和黑名单两种类型。白名单仅允许列表中的IP访问，黑名单拒绝列表中的IP访问。策略组支持添加单个IP地址（如192.168.1.1）和CIDR网段（如192.168.0.0/16）格式的条目。策略组修改后实时生效，无需重启SLB实例。选项B错误，一个监听只能绑定一种类型的策略组（白名单或黑名单），不能同时绑定两种。",ref:'help.aliyun.com/zh/slb/user-guide/访问控制/'},
  {id:'slb16',module:'负载均衡SLB',type:'judge',question:"阿里云SLB提供丰富的监控指标，包括每秒新建连接数、活跃连接数、非活跃连接数、入带宽、出带宽、每秒请求数等，用户可通过云监控服务查看这些指标并设置报警规则。",options:["正确","错误"],answer:[0],explanation:"SLB集成了云监控服务，提供多种监控指标，包括但不限于：每秒新建连接数（CPS）、活跃连接数、非活跃连接数、入方向带宽、出方向带宽、入方向数据包数、出方向数据包数、每秒请求数（QPS，适用于七层监听）、2xx/3xx/4xx/5xx状态码计数等。用户可在SLB控制台或云监控控制台查看这些指标，并可设置基于指标阈值的报警规则，通过短信、邮件等方式接收告警通知。",ref:'help.aliyun.com/zh/slb/user-guide/监控/'},
  {id:'slb17',module:'负载均衡SLB',type:'single',question:"关于SLB的X-Forwarded-For头部字段，以下说法正确的是？",options:["X-Forwarded-For用于传递客户端的真实IP地址，后端服务器可通过该字段获取访问者的真实来源IP","X-Forwarded-For仅在TCP监听中支持，HTTP和HTTPS监听不传递该字段","SLB会在X-Forwarded-For字段中替换原有值，仅保留SLB自身的IP地址","X-Forwarded-For字段不可配置，SLB始终强制添加该头部且无法关闭"],answer:[0],explanation:"当客户端通过SLB访问后端服务器时，后端服务器默认看到的是SLB的内网IP而非客户端真实IP。X-Forwarded-For（XFF）头部字段用于传递客户端的真实IP地址，后端服务器可通过解析该字段获取访问者的真实来源IP。该功能主要在HTTP和HTTPS七层监听中支持（TCP四层监听可通过Proxy Protocol获取）。SLB不会替换原有值，而是在已有的XFF值后面追加客户端IP。用户可在监听配置中开启或关闭X-Forwarded-For功能。",ref:'help.aliyun.com/zh/slb/user-guide/监听/X-Forwarded-For/'},
  {id:'slb18',module:'负载均衡SLB',type:'judge',question:"添加为SLB后端服务器的ECS实例必须处于\"运行中\"（Running）状态才能正常接收SLB转发的流量。如果ECS实例处于\"已停止\"状态，SLB健康检查会将其标记为异常并停止向其转发请求。",options:["正确","错误"],answer:[0],explanation:"添加为SLB后端服务器的ECS实例需要处于\"运行中\"状态才能正常处理请求。如果ECS实例处于\"已停止\"或其他非运行状态，SLB健康检查会将该服务器标记为异常状态，停止向其转发新的请求。当实例恢复\"运行中\"状态且健康检查通过后，SLB会自动将其重新加入转发列表。此外，后端ECS实例需与SLB实例在同一地域，且网络配置需保证SLB可访问后端服务器端口。",ref:'help.aliyun.com/zh/slb/user-guide/后端服务器/'},
  {id:'slb19',module:'负载均衡SLB',type:'single',question:"关于公网SLB实例的带宽配置，以下说法正确的是？",options:["SLB实例的带宽峰值由实例规格固定决定，无法调整","按使用流量计费的公网SLB实例可设置带宽峰值，超过峰值后流量会被限速","SLB实例的带宽不受任何限制，可以无限使用网络带宽","所有SLB实例的带宽峰值都默认为10 Gbps，不可修改"],answer:[1],explanation:"公网SLB实例的带宽配置取决于计费方式。按使用流量计费的公网SLB实例可设置带宽峰值（1到10000 Mbps），当流量超过设置峰值时会被限速，避免产生意外高额费用。按固定带宽计费的公网SLB实例带宽由所购买的带宽值决定。性能保障型SLB实例还有规格对应的流量处理能力上限。用户可根据业务需求选择合适的计费方式和带宽配置，也可通过升级实例规格获得更高性能。",ref:'help.aliyun.com/zh/slb/product-overview/计费方式/'},
  {id:'slb20',module:'负载均衡SLB',type:'multi',question:"关于SLB实例的计费方式，以下说法正确的有哪些？",options:["SLB实例支持按量付费和包年包月两种计费模式","公网SLB实例的公网带宽可选择按使用流量计费或按固定带宽计费","按量付费的SLB实例在创建后即开始计费，即使未配置监听和后端服务器也会产生实例费","包年包月SLB实例不支持随时升级规格，必须等到当前计费周期结束后才能变更"],answer:[0,1,2],explanation:"SLB实例支持按量付费和包年包月两种计费模式。公网SLB实例的公网带宽可选择按使用流量计费或按固定带宽计费。按量付费SLB实例创建后即开始按小时计费，即使未配置监听和后端服务器也会产生实例费和规格费（性能保障型）。选项D错误，包年包月SLB实例支持随时升级规格（升配），升级后立即生效，费用按天补差价；降配有限制但并非必须等到计费周期结束。",ref:'help.aliyun.com/zh/slb/product-overview/计费方式/'},
  {id:'oss01',module:'对象存储OSS',type:'single',question:"阿里云 OSS 中的 \"Bucket\" 是什么概念？",options:["存储空间（容器）","单个文件","文件夹","数据库表"],answer:[0],explanation:"Bucket 是 OSS 的顶级容器，类似于文件夹，用于存储对象（Object）。Bucket 名称全局唯一，创建后不可更改。",ref:'help.aliyun.com/zh/oss/'},
  {id:'oss02',module:'对象存储OSS',type:'multi',question:"OSS 提供的存储类型包括以下哪些？",options:["标准存储","低频访问存储","归档存储","极速存储"],answer:[0,1,2],explanation:"OSS 提供标准存储（频繁访问）、低频访问存储（较少访问）和归档存储（长期保存）三种类型。没有\"极速存储\"类型。",ref:'help.aliyun.com/zh/oss/'},
  {id:'oss03',module:'对象存储OSS',type:'single',question:"OSS 的\"生命周期规则\"主要用于什么？",options:["自动转换存储类型或删除过期文件","限制文件访问时间","设置文件版本","管理 Bucket 权限"],answer:[0],explanation:"生命周期规则可以自动将达到一定时间的文件转换为更低成本的存储类型（如标准转低频/归档），或自动删除过期文件，降低存储成本。",ref:'help.aliyun.com/zh/oss/'},
  {id:'oss04',module:'对象存储OSS',type:'judge',question:"OSS 中每个 Object 都有唯一的 Key，Key 的层级结构（如 a/b/c.txt）在 OSS 中实际表现为扁平结构。",options:["正确","错误"],answer:[0],explanation:"OSS 是扁平结构，Object 的 Key 可以模拟文件夹层级（如 a/b/c.txt），但底层存储并无真正的目录结构，仅通过 Key 前缀模拟。",ref:'help.aliyun.com/zh/oss/'},
  {id:'oss05',module:'对象存储OSS',type:'multi',question:"以下哪些是 OSS 的读写权限（ACL）设置？",options:["私有","公共读","公共读写","仅好友可见"],answer:[0,1,2],explanation:"OSS 的 Bucket/Object ACL 分为：私有（private）、公共读（public-read）和公共读写（public-read-write）。没有\"仅好友可见\"选项。",ref:'help.aliyun.com/zh/oss/'},
  {id:'oss06',module:'对象存储OSS',type:'single',question:"OSS 的\"防盗链\"功能主要通过什么机制实现？",options:["Referer 字段校验","IP 地址白名单","Token 认证","HTTPS 加密"],answer:[0],explanation:"OSS 防盗链主要通过配置 Referer 白名单/黑名单实现，只有来自指定 Referer 的请求才被允许访问，防止资源被其他网站盗用。",ref:'help.aliyun.com/zh/oss/'},
  {id:'oss07',module:'对象存储OSS',type:'judge',question:"OSS 的归档存储类型数据需要解冻（Restore）后才能读取。",options:["正确","错误"],answer:[0],explanation:"归档存储类型的数据需要先执行解冻操作，解冻完成后才能读取，解冻通常需要数分钟到数小时，适合极少访问的冷数据。",ref:'help.aliyun.com/zh/oss/'},
  {id:'oss08',module:'对象存储OSS',type:'single',question:"关于OSS Bucket的版本控制功能，以下说法正确的是？",options:["开启版本控制后，同名Object被覆盖时会保留旧版本，用户可随时恢复到任意历史版本","版本控制开启后不能暂停，且已产生的历史版本无法删除","版本控制只能在创建Bucket时开启，已有Bucket无法开启","开启版本控制后，删除Object时会立即永久删除所有版本，无法恢复"],answer:[0],explanation:"OSS版本控制功能开启后，对同名Object的覆盖和删除操作都会保留历史版本。覆盖操作会生成新版本同时保留旧版本，删除操作会添加一个删除标记（Delete Marker）而不是物理删除数据。用户可随时恢复到任意历史版本。版本控制可在创建Bucket时开启，也可在已有Bucket上开启。已开启版本控制的Bucket可以暂停版本控制（暂停后新上传的Object不再产生新版本，但已有的历史版本仍保留）。历史版本可通过生命周期规则自动删除或手动删除。",ref:'help.aliyun.com/zh/oss/user-guide/版本控制/'},
  {id:'oss09',module:'对象存储OSS',type:'single',question:"关于OSS跨区域复制（Cross-Region Replication）功能，以下说法正确的是？",options:["跨区域复制仅支持复制新增的Object，已存在的Object不会自动复制","跨区域复制可开启数据校验（基于CRC64校验码），确保源Bucket和目标Bucket的数据一致性","跨区域复制是同步进行的，源Bucket写入成功即表示目标Bucket也已写入完成","跨区域复制不支持复制Object的元数据（如Content-Type等）"],answer:[1],explanation:"OSS跨区域复制（CRR）可将源Bucket中的Object自动异步复制到另一个地域的目标Bucket。CRR支持开启数据校验（基于CRC64校验码），确保复制过程中数据的完整性和一致性。选项A错误，开启CRR时可选择是否复制历史数据（已存在的Object）。CRR是异步操作，源Bucket写入成功后系统在后台进行复制，存在一定延迟。CRR支持复制Object的数据和元数据（包括Content-Type、自定义元数据等），也支持复制版本控制相关的操作。",ref:'help.aliyun.com/zh/oss/user-guide/跨区域复制/'},
  {id:'oss10',module:'对象存储OSS',type:'multi',question:"关于使用STS（Security Token Service）进行OSS临时授权访问，以下说法正确的有哪些？",options:["STS临时凭证包含临时AccessKey ID、临时AccessKey Secret和安全令牌（SecurityToken），有有效期限制","STS临时凭证可精确控制权限范围和有效时间，适合分发给临时用户或移动端应用","STS临时凭证过期后可以自动续期，无需重新获取","通过STS获取的临时凭证可以用于OSS的所有操作，权限无法限定"],answer:[0,1],explanation:"STS（Security Token Service）提供临时访问凭证，包含临时AccessKey ID、临时AccessKey Secret和安全令牌（SecurityToken），具有有效期限制（最小15分钟，最大12小时）。STS临时凭证可通过RAM角色和权限策略精确控制权限范围和有效时间，非常适合分发给临时用户、移动端应用或跨账号访问场景。选项C错误，临时凭证过期后不能自动续期，需通过STS重新获取新的凭证。选项D错误，STS临时凭证的权限通过权限策略限定，可精确控制到具体的Bucket、Object和操作类型。",ref:'help.aliyun.com/zh/oss/user-guide/STS临时授权/'},
  {id:'oss11',module:'对象存储OSS',type:'single',question:"关于OSS签名URL（预签名URL），以下说法正确的是？",options:["签名URL只能用于下载Object，不支持上传操作","签名URL通过在URL中携带签名信息，允许第三方在指定有效期内访问指定的OSS资源","签名URL一旦生成，有效期不可更改，且无法提前撤销","签名URL不需要OSS AccessKey参与计算，任何人都可以生成"],answer:[1],explanation:"OSS签名URL（预签名URL）通过在URL中携带签名信息，允许第三方在指定的时间段内对指定的OSS资源进行访问（包括上传和下载操作）。签名URL使用OSS AccessKey ID和Secret结合请求参数计算签名。选项A错误，签名URL既支持下载（GET）也支持上传（PUT）操作。选项C错误，签名URL的有效期在生成时指定，虽然已生成的URL无法直接更改有效期，但可通过Bucket Policy或RAM策略控制访问权限来限制实际访问。选项D错误，签名URL的计算需使用AccessKey Secret进行签名，只有持有有效AccessKey的一方才能生成正确的签名URL。",ref:'help.aliyun.com/zh/oss/user-guide/签名URL/'},
  {id:'oss12',module:'对象存储OSS',type:'single',question:"关于OSS Multipart Upload（分片上传），以下说法正确的是？",options:["分片上传适用于大文件上传，将文件分成多个分片分别上传，最后合并成一个完整的Object","分片上传过程中如果某个分片上传失败，必须重新上传整个文件","分片上传不支持断点续传，所有分片必须一次性上传完成","分片上传的分片大小固定为1MB，不支持自定义"],answer:[0],explanation:"Multipart Upload（分片上传）是OSS为大文件上传提供的功能，将大文件分成多个分片（Part）分别上传，所有分片上传完成后通过Complete Multipart Upload操作合并成一个完整的Object。选项B错误，如果某个分片上传失败，只需重新上传该失败的分片，无需重传整个文件。选项C错误，分片上传支持断点续传，已上传成功的分片不需要重新上传。选项D错误，分片大小支持自定义（除最后一个分片外，每个分片最小100KB，最大5GB），可根据网络情况和文件大小灵活设置。",ref:'help.aliyun.com/zh/oss/user-guide/分片上传/'},
  {id:'oss13',module:'对象存储OSS',type:'judge',question:"OSS Bucket的外网访问域名格式为<BucketName>.<Endpoint>，其中Endpoint包含地域信息。同一Bucket可通过外网Endpoint、内网Endpoint和传输加速Endpoint等多种域名访问。",options:["正确","错误"],answer:[0],explanation:"OSS Bucket的域名格式为<BucketName>.<Endpoint>。Endpoint根据地域和网络类型不同分为多种：外网Endpoint（如oss-cn-hangzhou.aliyuncs.com）用于公网访问，内网Endpoint（如oss-cn-hangzhou-internal.aliyuncs.com）用于同地域ECS内网访问（免流），传输加速Endpoint（oss-accelerate.aliyuncs.com）用于全球加速访问。Bucket名称需全局唯一，命名规则为3到63个字符，只能包含小写字母、数字和短划线。自定义域名也可绑定到Bucket进行访问。",ref:'help.aliyun.com/zh/oss/user-guide/域名管理/'},
  {id:'oss14',module:'对象存储OSS',type:'single',question:"关于OSS的跨域资源共享（CORS）配置，以下说法正确的是？",options:["CORS配置用于允许网页应用从不同域名下的浏览器直接访问OSS资源","CORS规则一旦配置，对所有来源的跨域请求都生效，无法限制特定域名","CORS仅支持GET请求，不支持POST、PUT等HTTP方法","配置CORS后，OSS会在所有响应中自动添加Access-Control-Allow-Origin头部"],answer:[0],explanation:"CORS（Cross-Origin Resource Sharing）是W3C标准，用于允许网页应用从不同域名（跨域）的浏览器中直接访问OSS资源。OSS支持配置CORS规则，每条规则可指定允许的来源（Allowed Origin）、允许的方法（Allowed Method，包括GET、PUT、POST、DELETE、HEAD）、允许的头部（Allowed Header）和缓存时间（Max-Age）。选项B错误，CORS规则可精确指定允许的来源域名。选项C错误，CORS支持多种HTTP方法。选项D错误，OSS仅在请求匹配CORS规则时才添加相应的CORS响应头部。",ref:'help.aliyun.com/zh/oss/user-guide/跨域设置/'},
  {id:'oss15',module:'对象存储OSS',type:'judge',question:"OSS支持开启访问日志记录功能，开启后OSS会自动将Bucket的访问日志以JSON格式存储到指定的Bucket中。",options:["正确","错误"],answer:[1],explanation:"此说法错误。OSS访问日志记录功能确实支持开启，会将Bucket的访问日志自动记录到指定的Bucket中。但日志文件的格式不是JSON格式，而是以特定格式的文本文件存储，每条日志记录包含时间、操作者、操作类型、Bucket名称、Object名称、请求大小、响应状态码等字段，以空格分隔。日志文件每小时生成一次，按照特定的命名规则（如<TargetPrefix><SourceBucket>-YYYY-mm-DD-HH-MM-SS-UniqueString）存储在指定路径下。日志存储的目标Bucket必须与源Bucket在同一地域。",ref:'help.aliyun.com/zh/oss/user-guide/访问日志/'},
  {id:'oss16',module:'对象存储OSS',type:'single',question:"关于OSS静态网站托管功能，以下说法正确的是？",options:["OSS可将Bucket配置为静态网站托管模式，直接通过HTTP访问网页内容，无需额外服务器","静态网站托管仅支持HTML文件，不支持图片、CSS、JavaScript等静态资源","配置静态网站托管后，默认页面和错误页面只能使用根目录下的文件","静态网站托管不支持自定义域名绑定，只能使用OSS默认域名访问"],answer:[0],explanation:"OSS支持静态网站托管功能，可将Bucket配置为静态网站托管模式，通过HTTP协议直接提供网页访问，适用于托管静态网站（HTML、CSS、JavaScript、图片等静态资源）。选项B错误，静态网站托管支持所有类型的静态资源文件。选项C错误，默认页面和错误页面可指定任意路径下的文件（如index.html或pages/error.html）。选项D错误，静态网站托管支持绑定自定义域名（需完成域名备案和CNAME配置），建议使用自定义域名而非OSS默认域名（默认域名强制下载而非直接渲染）。",ref:'help.aliyun.com/zh/oss/user-guide/静态网站托管/'},
  {id:'oss17',module:'对象存储OSS',type:'multi',question:"关于OSS镜像回源（Mirror Back-to-Source）功能，以下说法正确的有哪些？",options:["当请求的Object在OSS中不存在时，OSS会自动从配置的源站获取该Object并返回给客户端，同时存储到OSS中","镜像回源获取的Object在存储到OSS后，后续相同请求将直接从OSS返回，不再回源","镜像回源规则中每条规则只能配置一个回源URL，但可配置多条规则匹配不同请求路径前缀","镜像回源功能不会在OSS中存储获取到的Object，每次请求都直接从源站获取并返回"],answer:[0,1,2],explanation:"镜像回源是OSS的回源规则之一，当客户端请求的Object在OSS中不存在（返回404）时，OSS会自动从配置的镜像源站获取该Object，返回给客户端同时存储到OSS中。后续相同请求直接从OSS返回，不再回源。每条回源规则配置一个源站URL，但可配置多条规则匹配不同前缀的请求。选项D错误，镜像回源获取的Object会存储到OSS中，后续相同请求直接从OSS返回。镜像回源适用于无缝迁移数据到OSS的场景。",ref:'help.aliyun.com/zh/oss/user-guide/镜像回源/'},
  {id:'oss18',module:'对象存储OSS',type:'judge',question:"对于通过简单上传（PUT Object）方式上传的小文件，OSS Object的ETag值通常为文件内容的MD5值；而对于通过Multipart Upload方式上传的文件，ETag值是各分片MD5值经特定算法组合计算的结果，不等于整个文件的MD5值。",options:["正确","错误"],answer:[0],explanation:"OSS Object的ETag是Object内容的标识符。对于通过简单上传（PUT Object）上传的小文件，ETag值通常等于文件内容的MD5值（对于启用了MD5校验的上传）。但对于通过Multipart Upload方式上传的文件，ETag值的计算方式不同，它是各分片ETag值经过特定算法组合后的结果（不是各分片MD5的简单拼接，也不是整个文件的MD5），因此通过Multipart Upload上传的文件ETag不等于整个文件的MD5值。ETag可用于判断Object内容是否发生变化，也可用于条件请求（If-Match/If-None-Match）。",ref:'help.aliyun.com/zh/oss/user-guide/'},
  {id:'oss19',module:'对象存储OSS',type:'single',question:"关于OSS Bucket的配额限制，以下说法正确的是？",options:["每个阿里云账号在每个地域可创建的Bucket数量有默认上限（通常为30个），可通过工单申请提升","单个Bucket的存储容量有固定上限，不能超过100TB","单个Object的最大大小不能超过1GB","每个Bucket只能存储100万个Object"],answer:[0],explanation:"每个阿里云账号在每个地域可创建的Bucket数量有默认上限（通过控制台、API创建的Bucket数量上限默认为30个每地域），如需更多可通过提交工单申请提升。选项B错误，单个Bucket的存储容量没有固定上限，可存储PB级别的数据。选项C错误，通过Multipart Upload方式上传的单个Object最大支持48.8TB，通过简单上传（PUT Object）单个Object最大支持5GB。选项D错误，单个Bucket可以存储的Object数量没有限制。",ref:'help.aliyun.com/zh/oss/product-overview/使用限制/'},
  {id:'oss20',module:'对象存储OSS',type:'multi',question:"关于OSS Select功能，以下说法正确的有哪些？",options:["OSS Select允许使用SQL语句直接从OSS中的CSV或JSON文件中查询数据，无需下载整个文件","OSS Select可减少网络传输量和客户端处理量，提升查询效率","OSS Select支持对GZIP压缩的CSV或JSON文件执行查询操作","OSS Select是一种全功能数据库查询引擎，支持复杂的JOIN和子查询操作"],answer:[0,1,2],explanation:"OSS Select功能允许用户使用简单的SQL语句直接从OSS中的CSV或JSON格式文件中检索所需的数据，无需下载整个文件到本地处理。这种方式大幅减少了网络传输量和客户端的处理量，提升了数据处理效率。OSS Select支持对GZIP压缩的CSV/JSON文件执行查询。选项D错误，OSS Select仅支持简单的SELECT查询（支持列选择、WHERE条件过滤等），不支持JOIN、子查询、聚合函数等复杂SQL操作，它不是全功能的关系型数据库查询引擎。",ref:'help.aliyun.com/zh/oss/user-guide/SelectObject/'},
  {id:'vpc01',module:'专有网络VPC',type:'single',question:"阿里云 VPC 的基本组成部分不包括以下哪项？",options:["子网","路由表","互联网网关","负载均衡器"],answer:[3],explanation:"VPC 的基本组成包括子网（VSwitch）、路由表、互联网网关等。负载均衡器（SLB）是独立产品，不属于 VPC 的基本组成。",ref:'help.aliyun.com/zh/vpc/'},
  {id:'vpc02',module:'专有网络VPC',type:'multi',question:"以下关于 VPC 说法正确的有哪些？",options:["VPC 是逻辑隔离的私有网络","不同 VPC 之间默认无法通信","VPC 内的子网可以跨可用区","VPC 创建后无法修改 CIDR 网段"],answer:[0,1,2],explanation:"VPC 是逻辑隔离的私有网络，不同 VPC 间默认隔离。VPC 内子网可以分布在不同可用区。VPC 的 CIDR 网段在创建后不可修改，但可以添加附加网段（此选项表述过于绝对，故不选）。",ref:'help.aliyun.com/zh/vpc/'},
  {id:'vpc03',module:'专有网络VPC',type:'single',question:"NAT 网关的主要作用是什么？",options:["提供 SNAT 和 DNAT 功能","加密网络传输","分配公网 IP","管理安全组规则"],answer:[0],explanation:"NAT 网关提供 SNAT（源地址转换，让 VPC 内无公网 IP 的实例访问外网）和 DNAT（目标地址转换，将外网请求映射到内网实例）功能。",ref:'help.aliyun.com/zh/vpc/'},
  {id:'vpc04',module:'专有网络VPC',type:'judge',question:"VPC 对等连接（VPC Peering）可以实现两个不同 VPC 之间的内网互通。",options:["正确","错误"],answer:[0],explanation:"VPC Peering 建立两个 VPC 之间的对等连接，使它们可以通过内网 IP 互相通信，无需通过公网，降低了延迟和成本。",ref:'help.aliyun.com/zh/vpc/'},
  {id:'vpc05',module:'专有网络VPC',type:'single',question:"VPC 中路由表的作用是什么？",options:["控制网络流量的转发路径","管理 ECS 实例规格","配置安全组规则","监控网络流量"],answer:[0],explanation:"路由表定义了 VPC 内网络流量的转发规则，决定数据包如何在不同子网、网关之间转发。每个子网必须关联一个路由表。",ref:'help.aliyun.com/zh/vpc/'},
  {id:'vpc06',module:'专有网络VPC',type:'single',question:"关于阿里云专有网络VPC，以下说法正确的是？",options:["VPC是公共云上全局的逻辑隔离网络环境，所有地域共享","VPC是用户在阿里云上为自己隔离出来的一块逻辑网络空间","同一地域下每个账号只能创建一个VPC","VPC只能包含一个可用区的交换机"],answer:[1],explanation:"VPC（Virtual Private Cloud）是用户在阿里云上为自己隔离出来的一块逻辑隔离的网络空间。VPC是区域级资源，不同地域的VPC相互隔离、互不通信；同一地域下每个账号可以创建多个VPC；一个VPC可以包含其所在地域内多个可用区（Available Zone）的交换机（VSwitch）。",ref:'help.aliyun.com/zh/vpc/'},
  {id:'vpc07',module:'专有网络VPC',type:'single',question:"在创建交换机（VSwitch）时，以下关于CIDR网段的描述正确的是？",options:["交换机的CIDR网段必须与所属VPC的CIDR网段完全相同","交换机的CIDR网段必须在所属VPC的CIDR网段范围内","交换机的CIDR网段可以与VPC的CIDR网段重叠","交换机的CIDR网段不受所属VPC CIDR网段的限制"],answer:[1],explanation:"交换机（VSwitch）的CIDR网段必须是其所属VPC CIDR网段的子集，即必须在VPC的CIDR范围内。同一VPC下不同交换机的CIDR网段不能重叠。交换机网段大小需在/16到/29之间（IPv4），且不能与VPC内其他交换机网段冲突。",ref:'help.aliyun.com/zh/vpc/'},
  {id:'vpc08',module:'专有网络VPC',type:'single',question:"关于VPC内的系统路由表和自定义路由表，以下说法正确的是？",options:["每个VPC只能拥有一张路由表","系统路由表可以被用户手动删除","自定义路由表可以关联到指定的交换机","交换机只能关联系统路由表，不能关联自定义路由表"],answer:[2],explanation:"每个VPC拥有一张系统路由表，且系统路由表不可删除。用户可以创建自定义路由表并关联到指定的交换机（VSwitch），实现不同交换机的差异化路由策略。一个交换机同一时间只能关联一张路由表，未关联自定义路由表时默认使用系统路由表。",ref:'help.aliyun.com/zh/vpc/'},
  {id:'vpc09',module:'专有网络VPC',type:'single',question:"关于NAT网关的SNAT和DNAT功能，以下说法正确的是？",options:["SNAT用于提供公网入口访问VPC内ECS，DNAT用于VPC内ECS访问公网","SNAT用于VPC内ECS访问公网，DNAT用于提供公网入口访问VPC内ECS","SNAT和DNAT都仅用于VPC内ECS访问公网","DNAT可以将一个公网IP同时映射到多台ECS实现负载均衡"],answer:[1],explanation:"SNAT（源地址转换）为VPC内无公网IP的ECS提供访问公网的能力；DNAT（目的地址转换）将NAT网关上的公网IP端口映射到VPC内ECS的私网IP端口，提供公网入口访问VPC内ECS。DNAT映射到单台ECS，不提供负载均衡功能（负载均衡由SLB实现）。",ref:'help.aliyun.com/zh/vpc/'},
  {id:'vpc10',module:'专有网络VPC',type:'single',question:"关于弹性公网IP（EIP），以下说法正确的是？",options:["EIP只能绑定到ECS实例上","EIP是区域级资源，只能绑定同地域的云资源","EIP一旦绑定到云资源上就不能解绑","EIP不支持独立购买，必须与ECS实例一起购买"],answer:[1],explanation:"弹性公网IP（EIP）是区域级资源，只能绑定同地域的云资源。EIP可以独立购买和持有，可绑定到ECS、NAT网关、SLB、ENI、高可用虚拟IP等多种云资源，绑定后可随时解绑并重新绑定到其他资源，灵活管理公网IP。",ref:'help.aliyun.com/zh/vpc/'},
  {id:'vpc11',module:'专有网络VPC',type:'single',question:"关于阿里云VPN网关，以下说法正确的是？",options:["VPN网关同时支持IPsec-VPN和SSL-VPN两种类型","一个VPN网关只能创建一个IPsec连接","IPsec-VPN不支持BGP动态路由协议","SSL-VPN用于建立站点到站点（Site-to-Site）的连接"],answer:[0],explanation:"阿里云VPN网关同时支持IPsec-VPN和SSL-VPN两种类型，可在创建VPN网关时选择开启。IPsec-VPN用于建立站点到站点的连接，一个VPN网关可创建多个IPsec连接，且支持BGP动态路由协议；SSL-VPN用于终端（客户端）远程接入VPC，而非站点到站点连接。",ref:'help.aliyun.com/zh/vpc/'},
  {id:'vpc12',module:'专有网络VPC',type:'single',question:"关于VPC对等连接（VPC Peering），以下说法正确的是？",options:["VPC对等连接具有传递性，A与B、B与C互通则A与C自动互通","建立对等连接的两个VPC的CIDR网段可以重叠","VPC对等连接可以跨账号建立","VPC对等连接建立后无需配置路由即可直接通信"],answer:[2],explanation:"VPC对等连接支持跨账号建立，发起端创建后需接收端接受才能生效。VPC对等连接不具备传递性；建立对等连接的两个VPC的CIDR网段不能重叠；连接建立后仍需在双方路由表中添加指向对等连接的路由条目才能通信。",ref:'help.aliyun.com/zh/vpc/'},
  {id:'vpc13',module:'专有网络VPC',type:'multi',question:"关于网络ACL（Network ACL），以下描述正确的有哪些？",options:["网络ACL是交换机（VSwitch）级别的安全控制","网络ACL是无状态的，需要同时配置入方向和出方向规则","网络ACL是有状态的，允许出站的请求其响应自动允许入站","网络ACL的规则按优先级顺序匹配，数字越小优先级越高"],answer:[0,1,3],explanation:"网络ACL是交换机级别的安全控制，作用于整个交换机。网络ACL是无状态的（与安全组不同），因此需要同时配置入方向和出方向规则，允许出站的请求其响应不会自动放行入站。网络ACL规则按优先级匹配，优先级数字越小优先级越高，匹配到第一条即停止。",ref:'help.aliyun.com/zh/vpc/'},
  {id:'vpc14',module:'专有网络VPC',type:'multi',question:"关于云企业网（CEN），以下描述正确的有哪些？",options:["CEN可以实现不同VPC之间的内网互通","CEN支持跨地域的网络实例互通","加入CEN的网络实例需要手动逐一配置路由","CEN支持VPC、边界路由器（VBR）、云连接网（CCN）等网络实例接入"],answer:[0,1,3],explanation:"CEN（Cloud Enterprise Network）可以实现不同VPC之间的内网互通，并支持跨地域互通。加入CEN的网络实例会自动学习并分发路由，无需手动逐一配置路由。CEN支持多种网络实例接入，包括VPC、VBR（边界路由器）、CCN（云连接网）等。",ref:'help.aliyun.com/zh/vpc/'},
  {id:'vpc15',module:'专有网络VPC',type:'multi',question:"关于高速通道（Express Connect），以下描述正确的有哪些？",options:["高速通道提供私网连接，数据传输不经公网","高速通道的物理专线可以由阿里云合作伙伴提供","高速通道仅能用于连接本地IDC和阿里云VPC，不支持跨地域","高速通道结合CEN可以实现跨地域的专线互通"],answer:[0,1,3],explanation:"高速通道提供专属的私网连接，数据不经公网，具有低延迟、高可靠、安全的特点。物理专线可以自行向运营商申请铺设，也可以通过阿里云合作伙伴（合作伙伴专线）提供。高速通道不仅可以连接本地IDC与VPC，结合CEN还能实现跨地域的专线互通，选项C中\"仅能\"描述错误。",ref:'help.aliyun.com/zh/vpc/'},
  {id:'vpc16',module:'专有网络VPC',type:'multi',question:"以下关于安全组（Security Group）和网络ACL的区别，正确的有哪些？",options:["安全组是ECS实例级别的安全控制，网络ACL是交换机级别的安全控制","安全组是有状态的，网络ACL是无状态的","流量进入ECS前会先经过网络ACL的检查，再经过安全组的检查","安全组和网络ACL都只支持允许规则，不支持拒绝规则"],answer:[0,1,2],explanation:"安全组是ECS实例（弹性网卡）级别的安全控制，网络ACL是交换机级别的安全控制。安全组是有状态的（允许出站则响应自动入站），网络ACL是无状态的（需分别配置出入规则）。流量路径上先经过网络ACL（交换机级）再经过安全组（实例级）。安全组只支持允许规则，但网络ACL同时支持允许和拒绝规则，因此选项D错误。",ref:'help.aliyun.com/zh/vpc/'},
  {id:'vpc17',module:'专有网络VPC',type:'judge',question:"VPC流日志（Flow Logs）可以捕获VPC中弹性网卡（ENI）的流量信息，并支持将日志投递到日志服务（SLS）进行存储和分析。",options:["正确","错误"],answer:[0],explanation:"VPC流日志功能可以捕获VPC中弹性网卡（ENI）的流入、流出流量信息，并支持将日志投递到阿里云日志服务（SLS）进行存储、查询和分析，便于网络运维、安全审计和故障排查。",ref:'help.aliyun.com/zh/vpc/'},
  {id:'vpc18',module:'专有网络VPC',type:'judge',question:"阿里云VPC支持IPv6，开通IPv6后系统会为VPC分配IPv6 CIDR网段，但该IPv6地址仅支持公网访问，不能用于VPC内部通信。",options:["正确","错误"],answer:[1],explanation:"阿里云VPC支持IPv6，开通后系统会为VPC分配IPv6 CIDR网段（默认/56）。IPv6地址既可以用于VPC内部通信，也可以用于公网访问（需为IPv6公网带宽开通公网带宽）。因此\"仅支持公网访问，不能用于VPC内通信\"的说法是错误的。",ref:'help.aliyun.com/zh/vpc/'},
  {id:'vpc19',module:'专有网络VPC',type:'judge',question:"阿里云VPC支持自定义DHCP选项集（DHCP Options Set），可以通过DHCP选项集为VPC内的ECS自定义DNS服务器、域名等网络配置。",options:["正确","错误"],answer:[0],explanation:"阿里云VPC支持DHCP选项集功能，用户可以创建DHCP选项集，自定义DNS服务器地址、域名、搜索域名等DHCP配置参数，并将其关联到VPC，使VPC内新创建或重启的ECS按自定义配置获取网络参数。",ref:'help.aliyun.com/zh/vpc/'},
  {id:'vpc20',module:'专有网络VPC',type:'judge',question:"在VPC中，若要使交换机内的ECS通过NAT网关的SNAT功能访问公网，只需创建NAT网关并配置SNAT条目即可，无需在交换机关联的路由表中添加路由。",options:["正确","错误"],answer:[1],explanation:"创建NAT网关并配置SNAT条目后，还需要在交换机关联的路由表（系统路由表或自定义路由表）中添加一条目标网段为0.0.0.0/0、下一跳指向NAT网关的自定义路由条目，交换机内的ECS才能通过SNAT访问公网。仅创建NAT网关和SNAT条目而不配置路由无法实现公网访问。",ref:'help.aliyun.com/zh/vpc/'},
  {id:'ess01',module:'弹性伸缩',type:'multi',question:"弹性伸缩（Auto Scaling）的核心组件包括哪些？",options:["伸缩组","伸缩配置","伸缩规则","负载均衡器"],answer:[0,1,2],explanation:"弹性伸缩由伸缩组（管理实例集合）、伸缩配置（实例模板）和伸缩规则（触发条件）三个核心组件构成。SLB 是可选的关联组件。",ref:'help.aliyun.com/zh/ess/'},
  {id:'ess02',module:'弹性伸缩',type:'single',question:"弹性伸缩的\"告警伸缩\"是基于什么触发的？",options:["云监控指标达到阈值","固定时间点","手动触发","ECS 实例重启"],answer:[0],explanation:"告警伸缩通过关联云监控指标（如 CPU 使用率），当指标达到设定的阈值时自动触发扩容或缩容，实现按需弹性。",ref:'help.aliyun.com/zh/ess/'},
  {id:'ess03',module:'弹性伸缩',type:'judge',question:"弹性伸缩的\"冷却时间\"是指在完成一次伸缩活动后的一段时间内，拒绝执行新的伸缩活动。",options:["正确","错误"],answer:[0],explanation:"冷却时间防止因指标波动导致频繁伸缩，在冷却时间内不执行新的伸缩活动，保障系统稳定性。",ref:'help.aliyun.com/zh/ess/'},
  {id:'ess04',module:'弹性伸缩',type:'single',question:"关于弹性伸缩的冷却时间（Cooldown），以下说法正确的是？",options:["冷却时间内，所有伸缩活动（包括定时任务和手动触发）均被拒绝","冷却时间对定时任务和手动触发的伸缩活动均生效","冷却时间仅在云监控报警任务触发的伸缩活动时生效","冷却时间默认值为600秒"],answer:[2],explanation:"冷却时间仅在云监控报警任务触发的伸缩活动时生效。当报警任务触发伸缩规则执行后，伸缩组进入冷却时间，在冷却时间内报警任务再次触发的伸缩活动会被跳过（拒绝）。定时任务和手动触发的伸缩活动不受冷却时间限制，以保证定时任务能在预定时间准确执行。冷却时间默认值为300秒，取值范围为0至86400秒。",ref:'help.aliyun.com/zh/ess/'},
  {id:'ess05',module:'弹性伸缩',type:'single',question:"弹性伸缩组中，最小实例数、期望实例数和最大实例数应满足以下哪种关系？",options:["期望实例数可以大于最大实例数","最小实例数<=期望实例数<=最大实例数","期望实例数必须等于最小实例数","最大实例数可以小于最小实例数"],answer:[1],explanation:"在伸缩组中，期望实例数必须满足：最小实例数<=期望实例数<=最大实例数。伸缩组会始终将实例数量维持在期望实例数。当报警或定时任务触发伸缩规则后，期望实例数会在最小和最大实例数范围内变化；若设置的期望实例数超出范围，系统会自动将其调整到合法区间内。",ref:'help.aliyun.com/zh/ess/'},
  {id:'ess06',module:'弹性伸缩',type:'single',question:"关于伸缩配置（Scaling Configuration），以下描述错误的是？",options:["一个伸缩配置只能属于一个伸缩组","伸缩组同一时间只能启用一个伸缩配置","伸缩配置包含实例规格、镜像、安全组等信息","更换伸缩配置会立即影响伸缩组中已在运行的实例"],answer:[3],explanation:"伸缩配置定义了弹性伸缩创建ECS实例时所使用的模板，包含实例规格、镜像、安全组、登录凭证等信息。一个伸缩配置只能属于一个伸缩组，一个伸缩组同一时间只能启用一个伸缩配置。更换或修改伸缩配置只对之后新创建的实例生效，不会影响已经在运行的实例；若需使现有实例应用新配置，需通过实例替换等方式重新创建。",ref:'help.aliyun.com/zh/ess/'},
  {id:'ess07',module:'弹性伸缩',type:'single',question:"弹性伸缩生命周期挂钩（Lifecycle Hook）的默认超时时间为多少？",options:["300秒","600秒","3600秒（1小时）","86400秒（1天）"],answer:[2],explanation:"生命周期挂钩可在伸缩活动过程中将实例挂起，使其处于等待状态（扩容时为Pending:Wait，缩容时为Terminating:Wait），以便在实例加入或移除伸缩组前执行自定义操作。生命周期挂钩的默认超时时间为3600秒（1小时）。在超时时间内可通过调用CompleteLifecycleAction接口或持续发送心跳延长等待；超时后实例按配置的继续或放弃策略执行后续流程。",ref:'help.aliyun.com/zh/ess/'},
  {id:'ess08',module:'弹性伸缩',type:'single',question:"伸缩组配置了多个交换机（多可用区）并采用均衡分布策略时，以下描述正确的是？",options:["按交换机优先级顺序依次创建实例","在各可用区之间尽量均匀分布ECS实例数量","只在第一个可用区创建实例直到资源不足","随机选择可用区创建实例"],answer:[1],explanation:"多可用区伸缩策略包含均衡分布和优先级两种。采用均衡分布策略时，弹性伸缩会尽量在各可用区（交换机）之间均匀分布ECS实例数量，使各可用区实例数差异最小，从而提高整体可用性。而优先级策略则按交换机配置顺序优先在第一个可用区创建实例，当该可用区资源不足或库存不足时再使用下一个可用区。",ref:'help.aliyun.com/zh/ess/'},
  {id:'ess09',module:'弹性伸缩',type:'single',question:"弹性伸缩与负载均衡SLB集成后，以下行为描述正确的是？",options:["伸缩组扩容时需手动将实例加入SLB后端服务器组","伸缩组扩容时自动将实例加入SLB，缩容时自动移除并释放实例","SLB健康检查异常的实例仍会保留在伸缩组中","一个伸缩组只能关联一个SLB实例"],answer:[1],explanation:"弹性伸缩与SLB集成后，伸缩组扩容时会自动将新创建的ECS实例添加到SLB后端服务器组并设置权重，缩容时会自动从SLB移除并释放实例，实现流量的自动分发与摘除。当SLB健康检查发现实例异常时，弹性伸缩会将其判定为不健康并移除替换。一个伸缩组可关联多个SLB实例（CLB/ALB），实现多负载均衡的分发能力。",ref:'help.aliyun.com/zh/ess/'},
  {id:'ess10',module:'弹性伸缩',type:'single',question:"在弹性伸缩中使用竞价实例（抢占式实例）以优化成本，以下说法正确的是？",options:["竞价实例按固定价格收费，价格与按量付费相同","竞价实例被回收时伸缩组不会自动补充实例","推荐使用多实例规格+多可用区+竞价实例组合以提高实例获取成功率","竞价实例不能用于任何生产业务"],answer:[2],explanation:"竞价实例（抢占式实例）价格随市场供需浮动，通常远低于按量付费，可用于成本优化。为降低竞价实例因市场价高于出价或库存不足被回收对业务的影响，弹性伸缩推荐采用多实例规格+多可用区+竞价实例的组合策略，以提高实例获取成功率与整体稳定性。当竞价实例被回收时，伸缩组会通过健康检查识别并自动补充新实例以维持期望实例数。",ref:'help.aliyun.com/zh/ess/'},
  {id:'ess11',module:'弹性伸缩',type:'single',question:"关于弹性伸缩的实例预热时间（Instance Warmup），以下描述正确的是？",options:["预热时间内实例不会计入伸缩组的实例数量","预热时间结束后实例才加入SLB后端服务器组","预热时间内实例不参与云监控报警任务相关指标的计算","预热时间对所有类型的伸缩规则均无影响"],answer:[2],explanation:"实例预热时间用于在ECS实例启动后给予其一定的初始化时间。在预热时间内，该实例不会参与云监控报警任务相关指标（如CPU利用率）的计算，避免新实例未就绪导致指标失真而触发误判。预热时间内实例仍会计入伸缩组实例数量，加入SLB的时机与预热时间无直接关系。预热时间主要影响目标追踪规则和步进规则等基于指标的伸缩判断。",ref:'help.aliyun.com/zh/ess/'},
  {id:'ess12',module:'弹性伸缩',type:'multi',question:"弹性伸缩支持以下哪些类型的伸缩规则？",options:["简单规则","目标追踪规则","步进规则","固定容量规则"],answer:[0,1,2],explanation:"弹性伸缩支持的伸缩规则类型包括：简单规则（调整指定数量或百分比的实例）、目标追踪规则（根据云监控指标如平均CPU利用率自动调整使指标维持在目标值附近）、步进规则（根据指标值所在区间进行不同幅度的调整）以及预测规则（基于历史数据预测并预扩容）。固定容量规则不是ESS的伸缩规则类型。",ref:'help.aliyun.com/zh/ess/'},
  {id:'ess13',module:'弹性伸缩',type:'multi',question:"弹性伸缩与RDS集成后，可以实现以下哪些功能？",options:["扩容时自动将ECS实例内网IP加入RDS白名单","缩容时自动从RDS白名单移除对应ECS实例内网IP","自动创建RDS数据库账号","自动调整RDS实例规格"],answer:[0,1],explanation:"弹性伸缩与RDS集成后，伸缩组扩容时会自动将新创建ECS实例的内网IP添加到关联RDS实例的IP白名单中，使新实例能够访问数据库；缩容时会自动从RDS白名单中移除对应实例的内网IP，保证白名单的及时更新与安全。弹性伸缩不会自动创建RDS数据库账号，也不会自动调整RDS实例规格，这些属于RDS自身的管理操作。",ref:'help.aliyun.com/zh/ess/'},
  {id:'ess14',module:'弹性伸缩',type:'multi',question:"关于弹性伸缩对伸缩组内ECS实例的健康检查，以下说法正确的有哪些？",options:["当ECS实例状态不为运行中（Running）时，弹性伸缩会将其判定为不健康","关联SLB后，弹性伸缩可基于SLB健康检查结果判断实例健康状态","被判定为不健康的实例会被弹性伸缩移出伸缩组并释放","健康检查异常的实例会自动重启而不会被移除"],answer:[0,1,2],explanation:"弹性伸缩通过健康检查保障伸缩组实例可用性：当ECS实例状态不为运行中（Running）时，会被判定为不健康；当伸缩组关联SLB后，弹性伸缩可结合SLB健康检查结果判断实例是否健康。被判定为不健康的实例，弹性伸缩会将其移出伸缩组并释放（停机回收模式下则停止），同时自动创建新实例以维持期望实例数。弹性伸缩不会自动重启异常实例，而是采用移除替换的方式。",ref:'help.aliyun.com/zh/ess/'},
  {id:'ess15',module:'弹性伸缩',type:'multi',question:"关于云监控报警任务触发的弹性伸缩，以下描述正确的有哪些？",options:["报警任务基于云监控指标，如CPU利用率、内存利用率等","触发报警后执行关联的伸缩规则","报警任务触发的伸缩活动受伸缩组冷却时间限制","报警任务只能触发扩容，不能触发缩容"],answer:[0,1,2],explanation:"云监控报警任务是弹性伸缩的重要触发方式，基于云监控指标（如CPU利用率、内存利用率、系统负载等）进行监控。当指标满足报警条件（阈值持续若干个周期）时，触发关联的伸缩规则执行伸缩活动。报警任务触发的伸缩活动受伸缩组冷却时间限制，在冷却时间内报警任务触发的伸缩活动会被跳过。报警任务既可触发扩容也可触发缩容，以实现自动化的双向弹性。",ref:'help.aliyun.com/zh/ess/'},
  {id:'ess16',module:'弹性伸缩',type:'multi',question:"弹性伸缩伸缩组支持的伸缩模式包括以下哪些？",options:["标准模式（普通模式）","停机回收模式","抢占式模式","容器模式"],answer:[0,1],explanation:"弹性伸缩伸缩组支持两种伸缩模式：标准模式（普通模式），扩容时创建新ECS实例，缩容时释放实例；停机回收模式（Swing模式），缩容时将实例停止而非释放，扩容时优先启动已停止的实例，启动速度更快，适用于需要快速弹性响应的场景。抢占式模式属于实例付费类型而非伸缩模式，容器模式也不属于伸缩组的伸缩模式分类。",ref:'help.aliyun.com/zh/ess/'},
  {id:'ess17',module:'弹性伸缩',type:'judge',question:"弹性伸缩的冷却时间对定时任务触发的伸缩活动同样生效。",options:["正确","错误"],answer:[1],explanation:"错误。弹性伸缩的冷却时间仅在云监控报警任务触发的伸缩活动时生效，定时任务和手动触发的伸缩活动不受冷却时间限制。这是为了确保定时任务能够在预定时间准确执行伸缩动作，不受冷却期影响。",ref:'help.aliyun.com/zh/ess/'},
  {id:'ess18',module:'弹性伸缩',type:'judge',question:"弹性伸缩中，当竞价实例因市场价格或库存原因被回收时，伸缩组会通过健康检查自动补充新实例以维持期望实例数。",options:["正确","错误"],answer:[0],explanation:"正确。竞价实例（抢占式实例）被回收时，伸缩组会通过健康检查识别到实例不再处于运行中状态，将其判定为不健康并移除，然后自动创建新实例（可继续使用竞价实例）以维持伸缩组的期望实例数，从而保证业务连续性。",ref:'help.aliyun.com/zh/ess/'},
  {id:'ess19',module:'弹性伸缩',type:'judge',question:"生命周期挂钩可以同时作用于扩容（实例加入）和缩容（实例移除）两种场景。",options:["正确","错误"],answer:[0],explanation:"正确。生命周期挂钩支持两种场景：扩容时实例处于Pending:Wait等待状态，缩容时实例处于Terminating:Wait等待状态。用户可根据需要分别创建针对扩容和缩容的生命周期挂钩，在实例加入或移除伸缩组前执行自定义脚本或操作（如应用初始化、数据备份、优雅下线等）。",ref:'help.aliyun.com/zh/ess/'},
  {id:'ess20',module:'弹性伸缩',type:'judge',question:"伸缩组配置多个交换机时，必须采用均衡分布策略，不能采用优先级策略。",options:["正确","错误"],answer:[1],explanation:"错误。伸缩组配置多个交换机（多可用区）时，支持均衡分布和优先级两种多可用区伸缩策略。均衡分布策略在各可用区间尽量均匀分布实例；优先级策略按交换机配置顺序优先在第一个可用区创建实例，资源不足时再使用后续可用区。用户可根据业务对可用性和成本的需求选择合适的策略，并非必须采用均衡分布。",ref:'help.aliyun.com/zh/ess/'},
  {id:'sec01',module:'云安全',type:'single',question:"阿里云 RAM（访问控制）的主要功能是什么？",options:["管理用户身份与资源访问权限","监控网络流量","防御 DDoS 攻击","加密数据存储"],answer:[0],explanation:"RAM（Resource Access Management）用于管理云账号下的用户身份、角色和权限，实现最小权限原则下的资源访问控制。",ref:'help.aliyun.com/zh/ram/'},
  {id:'sec02',module:'云安全',type:'multi',question:"以下哪些属于阿里云安全产品（云盾）的组成部分？",options:["DDoS 防护","WAF Web 应用防火墙","堡垒机","对象存储 OSS"],answer:[0,1,2],explanation:"DDoS 防护、WAF 和堡垒机都属于云盾安全产品体系。OSS 是存储产品，不属于安全产品。",ref:'help.aliyun.com/zh/security/'},
  {id:'sec03',module:'云安全',type:'judge',question:"WAF（Web 应用防火墙）可以防护 SQL 注入、XSS 等 Web 攻击。",options:["正确","错误"],answer:[0],explanation:"WAF 专门防护 OWASP Top 10 等 Web 应用层攻击，包括 SQL 注入、XSS 跨站脚本、CC 攻击等。",ref:'help.aliyun.com/zh/waf/'},
  {id:'sec04',module:'云安全',type:'single',question:"安全组本质上是一种什么？",options:["实例级别的虚拟防火墙","网络级别的物理防火墙","操作系统级别的杀毒软件","应用级别的 WAF"],answer:[0],explanation:"安全组是 ECS 实例级别的虚拟防火墙，通过控制入站/出站规则来管控网络访问，作用于实例维度。",ref:'help.aliyun.com/zh/ecs/'},
  {id:'sec05',module:'云安全',type:'single',question:"DDoS高防IP通过哪种方式将正常用户的流量引导至源站服务器？",options:["直接在源站服务器上安装代理软件进行流量转发","通过DNS解析将域名指向高防IP，高防IP清洗后回源到源站","在源站服务器上配置路由规则将流量转发到高防集群","通过修改源站服务器的网关地址实现流量牵引"],answer:[1],explanation:"DDoS高防IP的工作原理是通过DNS解析将域名A记录或CNAME指向高防IP，所有访问流量先经过高防IP集群进行清洗，过滤掉恶意攻击流量后，将正常流量回源到源站服务器，从而保护源站不受DDoS攻击影响。",ref:'help.aliyun.com/zh/anti-ddos/'},
  {id:'sec06',module:'云安全',type:'single',question:"阿里云云安全中心（原安骑士）的\"基线检查\"功能主要用于检测什么？",options:["检测ECS实例的CPU和内存使用率是否超过阈值","检测服务器操作系统和数据库的配置是否符合安全最佳实践","检测网络流量的异常波动情况","检测云盘的磁盘I/O性能瓶颈"],answer:[1],explanation:"云安全中心的基线检查功能用于对服务器操作系统（如CentOS、Windows等）和数据库（如MySQL、Redis等）的安全配置进行自动化检查，对比CIS等安全基准标准，发现弱口令、配置不当、不必要的服务端口等安全风险，帮助用户满足等保合规要求。",ref:'help.aliyun.com/zh/security-center/'},
  {id:'sec07',module:'云安全',type:'single',question:"关于阿里云堡垒机的核心功能，以下说法正确的是？",options:["堡垒机仅支持SSH协议，不支持RDP远程桌面协议","堡垒机可以对运维人员的操作进行录像审计，但不支持实时阻断高危操作","堡垒机提供统一运维入口，支持身份认证、权限管理和操作审计","堡垒机只能管理阿里云ECS实例，不支持管理非阿里云服务器"],answer:[2],explanation:"阿里云堡垒机（云堡垒机）提供统一的运维安全管控入口，支持SSH和RDP等多种协议，集成了身份认证（如双因素认证）、权限管理（基于角色的访问控制）、操作审计（录像和指令级审计）以及实时运维管控（包括高危命令阻断）等功能。堡垒机既可管理阿里云ECS，也可管理非阿里云服务器。",ref:'help.aliyun.com/zh/bastion-host/'},
  {id:'sec08',module:'云安全',type:'single',question:"在阿里云SSL证书服务中，关于DV、OV、EV证书的区别，以下描述正确的是？",options:["DV证书需要验证企业资质，审核周期最长","EV证书在部分浏览器地址栏会显示企业名称","OV证书仅验证域名所有权，不验证组织信息","三种证书的加密强度不同，EV加密强度最高"],answer:[1],explanation:"DV（域名验证型）证书仅验证域名所有权，签发速度快；OV（组织验证型）证书需要验证企业/组织身份信息；EV（扩展验证型）证书审核最严格，在支持EV显示的浏览器中地址栏会显示绿色企业名称。三种证书的加密强度取决于密钥长度（如RSA 2048），与验证级别无直接关系。",ref:'help.aliyun.com/zh/ssl-certificate/'},
  {id:'sec09',module:'云安全',type:'single',question:"阿里云密钥管理服务KMS中，用户主密钥（CMK）的密钥材料可以由谁提供？",options:["只能由KMS服务自动生成，不支持外部导入","只能由用户自行生成并导入，KMS不提供生成功能","可以由KMS自动生成，也支持用户自带密钥材料（BYOK）导入","只能通过硬件安全模块HSM离线生成后邮寄给阿里云"],answer:[2],explanation:"阿里云KMS支持两种密钥材料来源：一是KMS服务自动生成密钥材料（默认方式）；二是用户自带密钥（Bring Your Own Key, BYOK），即用户自行生成密钥材料后通过KMS API导入。导入外部密钥材料时，密钥材料在KMS外部生成，导入后由KMS进行加密存储和使用管理。",ref:'help.aliyun.com/zh/kms/'},
  {id:'sec10',module:'云安全',type:'single',question:"阿里云云防火墙的访问控制功能主要工作在OSI模型的哪一层？",options:["物理层","数据链路层","传输层和网络层","应用层"],answer:[2],explanation:"阿里云云防火墙主要工作在OSI模型的网络层和传输层（即3层和4层），基于五元组（源IP、目的IP、源端口、目的端口、协议）进行访问控制，支持南北向流量（互联网与云资源之间）和东西向流量（VPC内资源之间）的防护。",ref:'help.aliyun.com/zh/cloud-firewall/'},
  {id:'sec11',module:'云安全',type:'single',question:"阿里云内容安全服务支持对以下哪种内容进行自动检测？",options:["仅支持文本内容的涉政暴恐检测","仅支持图片内容的鉴黄检测","支持文本、图片、视频等多种媒介的违规内容检测","仅支持语音内容的实时转写和审核"],answer:[2],explanation:"阿里云内容安全（绿网）服务支持对文本、图片、视频、语音、文件等多种媒介类型进行自动化内容检测，检测范围包括涉政、暴恐、色情、广告、辱骂、违禁品等多维度违规内容，广泛应用于UGC内容审核、直播审核等场景。",ref:'help.aliyun.com/zh/content-security/'},
  {id:'sec12',module:'云安全',type:'single',question:"根据网络安全等级保护2.0（等保2.0）标准，阿里云作为云服务商需要承担的安全责任属于？",options:["仅承担物理环境安全责任","承担云平台基础设施的安全责任，与云租户共同承担安全责任","承担租户应用层的全部安全责任","不承担任何安全责任，全部由租户负责"],answer:[1],explanation:"等保2.0采用\"责任共担模型\"。阿里云作为云服务商负责云平台基础设施（包括物理环境、宿主机、虚拟化层、云平台网络等）的安全，云租户负责其在云上部署的应用系统、数据、操作系统（IaaS模式下）等的安全。双方共同承担等保合规责任。",ref:'help.aliyun.com/zh/security-compliance/'},
  {id:'sec13',module:'云安全',type:'multi',question:"关于阿里云RAM中\"RAM用户（子账号）\"和\"RAM角色\"的区别，以下说法正确的有？",options:["RAM用户拥有永久访问密钥（AccessKey），RAM角色不拥有永久凭证","RAM用户通过用户名密码或AccessKey进行身份验证，RAM角色通过扮演（AssumeRole）获取临时凭证","RAM角色可以被任何经过授权的实体（包括跨账号实体）扮演","RAM用户和RAM角色都可以直接登录阿里云控制台"],answer:[0,1,2],explanation:"RAM用户（子账号）拥有独立的身份凭证（密码和AccessKey），是永久性的长期凭证；RAM角色是虚拟身份，不拥有永久凭证，需要通过STS AssumeRole API获取临时安全凭证（STS Token）来扮演。RAM角色可以被可信实体（包括跨阿里云账号的RAM用户）扮演。RAM角色本身不能直接登录控制台，需要通过扮演角色的方式获取临时凭证后访问。",ref:'help.aliyun.com/zh/ram/'},
  {id:'sec14',module:'云安全',type:'multi',question:"在阿里云RAM策略JSON语法中，以下元素描述正确的有？",options:["Effect字段取值为Allow或Deny，Deny优先级高于Allow","Action字段用于指定允许或拒绝的API操作，格式为\"服务名:操作名\"","Resource字段使用ACS ARN格式标识资源，格式为acs:服务名:地域:账号ID:资源","Condition字段是必填字段，必须指定条件限制"],answer:[0,1,2],explanation:"RAM策略JSON包含Version、Statement等元素。每个Statement中Effect（必填）取值为Allow或Deny，且Deny优先；Action（必填）格式如ecs:DescribeInstances；Resource使用ACS ARN格式acs:服务名:地域:账号ID:资源；Condition为可选字段，用于设置策略生效条件（如IP限制、时间限制等），非必填。",ref:'help.aliyun.com/zh/ram/'},
  {id:'sec15',module:'云安全',type:'multi',question:"关于阿里云STS（Security Token Service）临时安全凭证，以下说法正确的有？",options:["STS临时凭证包含AccessKey ID、AccessKey Secret和Security Token三部分","STS临时凭证有有效期限制，过期后自动失效","STS临时凭证可以自定义权限范围，通过RAM角色策略限定可访问的资源和操作","STS临时凭证的有效期可以设置为永不过期，适合长期使用场景"],answer:[0,1,2],explanation:"STS临时凭证由AccessKey ID、AccessKey Secret和Security Token三部分组成，具有有效期限制（最小900秒，最大12小时或更短取决于角色配置），过期后自动失效。STS凭证的权限受所扮演RAM角色的权限策略约束，可以实现最小权限授权。STS临时凭证不适合长期使用场景，长期访问应使用RAM用户的AccessKey或RAM角色扮演。",ref:'help.aliyun.com/zh/ram/'},
  {id:'sec16',module:'云安全',type:'multi',question:"关于阿里云数据加密服务，以下说法正确的有？",options:["数据加密服务提供专属密码机（HSM）实例，满足金融级合规要求","数据加密服务支持国密算法SM2/SM3/SM4","数据加密服务可与KMS集成，通过KMS统一管理HSM中的密钥","数据加密服务是免费服务，所有用户均可直接使用"],answer:[0,1,2],explanation:"阿里云数据加密服务（Data Encryption Service）提供经国家密码管理局认证的专属密码机（HSM）实例，支持国密算法（SM2/SM3/SM4）和国际算法（RSA/AES等），满足金融等行业合规要求。该服务可与KMS集成，通过KMS统一管理HSM中的密钥。数据加密服务为付费服务，需要单独购买HSM实例。",ref:'help.aliyun.com/zh/kms/'},
  {id:'sec17',module:'云安全',type:'judge',question:"阿里云安全组默认情况下入方向允许所有流量通过。",options:["正确","错误"],answer:[1],explanation:"阿里云安全组规则支持分别配置入方向和出方向规则，但默认情况下，安全组的入方向规则为\"拒绝所有流量\"（仅允许同一安全组内实例互相访问），出方向规则为\"允许所有流量\"。用户需要手动添加入方向放行规则才能允许外部访问。",ref:'help.aliyun.com/zh/ecs/'},
  {id:'sec18',module:'云安全',type:'judge',question:"云盾态势感知（云安全中心）可以汇聚阿里云多款安全产品的告警数据，进行关联分析和威胁可视化展示。",options:["正确","错误"],answer:[0],explanation:"云安全中心（原态势感知）是阿里云统一的安全运营平台，可以汇聚云防火墙、WAF、安骑士、DDoS防护等多款安全产品的告警和日志数据，通过关联分析、威胁情报匹配和机器学习算法，实现统一威胁检测、安全事件可视化和自动化响应编排。",ref:'help.aliyun.com/zh/security-center/'},
  {id:'sec19',module:'云安全',type:'judge',question:"DDoS高防IP的弹性防护带宽是指当攻击流量超过保底防护带宽时，系统会自动弹性扩展防护能力，按实际防护峰值计费。",options:["正确","错误"],answer:[0],explanation:"DDoS高防IP提供保底防护带宽和弹性防护带宽两种规格。保底防护是基础防护能力（包月付费），弹性防护是当攻击流量超过保底带宽时自动启动的扩展防护能力，按实际产生的弹性防护峰值按量计费（后付费），用户可设置弹性防护带宽上限。",ref:'help.aliyun.com/zh/anti-ddos/'},
  {id:'sec20',module:'云安全',type:'judge',question:"在阿里云KMS中，用户主密钥（CMK）被删除后可以立即恢复，密钥材料不会丢失。",options:["正确","错误"],answer:[1],explanation:"KMS中的CMK删除采用\"计划删除\"机制，用户发起删除请求后，CMK会进入7-30天（可配置）的待删除状态，在此期间CMK不可使用但可以取消删除。待删除期结束后，CMK及其密钥材料将被永久删除，无法恢复。因此在删除CMK前需要谨慎确认。",ref:'help.aliyun.com/zh/kms/'},
  {id:'cdn01',module:'内容分发CDN',type:'single',question:"CDN 加速的基本原理是什么？",options:["将内容缓存到离用户更近的边缘节点","压缩源站文件大小","增加源站服务器数量","使用更快的网络线路"],answer:[0],explanation:"CDN 通过将源站内容分发到全球各地的边缘节点，用户访问时由最近的节点响应，减少网络延迟，提高访问速度。",ref:'help.aliyun.com/zh/cdn/'},
  {id:'cdn02',module:'内容分发CDN',type:'judge',question:"CDN 的\"刷新预热\"功能中，\"预热\"是指主动将内容推送到边缘节点缓存。",options:["正确","错误"],answer:[0],explanation:"刷新是清除边缘节点缓存（强制下次请求回源），预热是主动将内容推送到节点缓存（用户首次访问即可命中缓存）。",ref:'help.aliyun.com/zh/cdn/'},
  {id:'cdn03',module:'内容分发CDN',type:'single',question:"在阿里云CDN中添加加速域名时，以下哪个信息是必须配置的？",options:["源站信息","缓存过期时间规则","HTTPS证书","自定义HTTP响应头"],answer:[0],explanation:"添加CDN加速域名时必须配置源站信息（包括源站类型和源站地址），因为CDN节点需要知道从哪里获取源站内容。缓存过期时间、HTTPS证书和自定义HTTP响应头都是可选配置，可以在域名添加后再进行设置。",ref:'help.aliyun.com/zh/cdn/'},
  {id:'cdn04',module:'内容分发CDN',type:'single',question:"阿里云CDN支持的源站类型不包括以下哪项？",options:["OSS Bucket","ECS实例的公网IP","自定义域名","本地局域网私有IP地址"],answer:[3],explanation:"阿里云CDN支持的源站类型包括：OSS Bucket（直接选择阿里云对象存储Bucket作为源站）、IP地址（支持ECS实例公网IP或其他公网IP）、域名（自定义域名作为源站）、函数计算（FC）。本地局域网私有IP地址无法被CDN节点访问，不能作为源站。",ref:'help.aliyun.com/zh/cdn/'},
  {id:'cdn05',module:'内容分发CDN',type:'single',question:"CDN节点回源时，如果源站返回304状态码，CDN节点的处理方式是？",options:["向客户端返回304，并删除节点上已缓存的文件","向客户端返回304，CDN节点继续使用已缓存的文件内容","向客户端返回200，并重新从源站下载完整内容","向客户端返回502错误，表示源站异常"],answer:[1],explanation:"当CDN节点回源时，源站返回304（Not Modified）表示客户端缓存的内容仍然有效，资源未修改。CDN节点会向客户端返回304响应，同时节点上已缓存的文件内容继续保留使用，不会删除缓存内容，也不会重新下载完整文件。",ref:'help.aliyun.com/zh/cdn/'},
  {id:'cdn06',module:'内容分发CDN',type:'single',question:"在阿里云CDN中，关于缓存过期时间的优先级，以下描述正确的是？",options:["源站响应头中的Cache-Control优先级恒定高于CDN控制台配置的缓存规则","CDN控制台配置的缓存规则优先级恒定高于源站响应头","用户可以在CDN控制台选择是否遵循源站Cache-Control，并可配置覆盖策略","缓存过期时间只能由CDN控制台统一配置，源站配置无效"],answer:[2],explanation:"阿里云CDN缓存过期时间的优先级可以通过控制台配置。用户可以选择\"遵循源站\"（即以源站的Cache-Control或Expires响应头为准）或\"不遵循源站\"（以CDN控制台配置的缓存规则为准）。当不遵循源站时，CDN控制台配置的缓存规则优先级高于源站响应头。用户还可以配置多条缓存规则，按规则匹配顺序生效。",ref:'help.aliyun.com/zh/cdn/'},
  {id:'cdn07',module:'内容分发CDN',type:'single',question:"阿里云CDN的计费方式中，按流量计费和按带宽计费的主要区别是？",options:["按流量计费按月固定收费，按带宽计费按使用量收费","按流量计费按CDN节点产生的下行流量收费，按带宽计费按日峰值带宽收费","两种计费方式完全相同，只是展示方式不同","按流量计费只适用于视频加速，按带宽计费只适用于下载加速"],answer:[1],explanation:"阿里云CDN的按流量计费是按照CDN节点向用户终端传输的下行数据流量（单位：GB/月）进行计费，适合流量波动较大的场景。按带宽计费是按照每日的带宽峰值（单位：Mbps，通常取5分钟粒度的日峰值）进行计费，适合带宽稳定且较高的场景。两种计费方式不能同时使用，用户可以根据业务特点选择更经济的计费方式，且支持变更。",ref:'help.aliyun.com/zh/cdn/'},
  {id:'cdn08',module:'内容分发CDN',type:'single',question:"在阿里云CDN中启用HTTPS加速时，关于证书配置的说法正确的是？",options:["CDN只支持从阿里云SSL证书服务申请的证书，不支持上传第三方证书","可以选择阿里云SSL证书服务中的免费证书，也可以上传自有证书","启用HTTPS后，CDN节点到源站的回源也必须使用HTTPS","CDN HTTPS加速不支持开启HTTP/2协议"],answer:[1],explanation:"阿里云CDN的HTTPS加速配置支持多种证书来源：可以从阿里云SSL证书服务中选择已签发的证书（包括免费DV证书），也可以手动上传第三方CA签发的证书和私钥。启用HTTPS后，回源协议可独立配置为HTTP或HTTPS，不强制使用HTTPS回源。CDN支持HTTP/2协议，可在HTTPS开启后启用。",ref:'help.aliyun.com/zh/cdn/'},
  {id:'cdn09',module:'内容分发CDN',type:'single',question:"阿里云CDN的URL鉴权功能中，Type A鉴权方式的URL中必须包含的参数是？",options:["签名密钥（PrivateKey）","时间戳和签名值（md5hash）","用户IP地址和User-Agent","请求域名和端口号"],answer:[1],explanation:"阿里云CDN的URL鉴权Type A方式中，鉴权URL格式为：http://DomainName/Filename?auth_key=timestamp-rand-uid-md5hash。其中timestamp为签发时间戳，md5hash是根据URI、PrivateKey、timestamp等参数计算出的MD5签名。PrivateKey（私钥）不直接出现在URL中，而是用于计算签名，以保证安全性。",ref:'help.aliyun.com/zh/cdn/'},
  {id:'cdn10',module:'内容分发CDN',type:'single',question:"在阿里云CDN中开启Range回源功能的主要目的是？",options:["提高CDN节点缓存命中率","支持大文件分片回源，减少回源带宽和首包时间","防止源站被恶意请求攻击","实现CDN节点的跨地域负载均衡"],answer:[1],explanation:"Range回源是指CDN节点在回源获取大文件时，通过HTTP Range请求头向源站请求文件的部分内容（分片），而非整个文件。这样可以减少单次回源的数据传输量，降低源站带宽压力，同时加快用户首包响应时间（用户可以更快开始播放视频或下载文件）。Range回源特别适用于大文件下载和视频点播加速场景。",ref:'help.aliyun.com/zh/cdn/'},
  {id:'cdn11',module:'内容分发CDN',type:'single',question:"阿里云CDN中\"刷新\"（Refresh）操作的作用是？",options:["将源站的最新内容主动推送到CDN节点缓存","强制删除CDN节点上的缓存文件，使用户下次请求时重新回源获取最新内容","重启CDN节点服务器，释放系统资源","更新CDN加速域名的DNS解析记录"],answer:[1],explanation:"CDN刷新操作会强制删除CDN节点上已缓存的文件内容。刷新后，当用户再次请求这些文件时，CDN节点缓存中没有对应内容，会回源获取最新内容并重新缓存。刷新可以按URL刷新（刷新指定文件）或按目录刷新（刷新目录下所有文件）。注意刷新与预热不同：预热是主动推送内容到节点，刷新是删除缓存。",ref:'help.aliyun.com/zh/cdn/'},
  {id:'cdn12',module:'内容分发CDN',type:'multi',question:"关于阿里云CDN预热（Prefetch）功能，以下说法正确的有？",options:["预热是将源站内容主动推送到CDN节点缓存，用户访问时无需回源","预热可以减少用户首次访问时的延迟","预热操作立即生效，预热完成后所有CDN节点均已缓存该内容","预热和刷新是同一操作的两个别名"],answer:[0,1],explanation:"CDN预热是指用户主动将源站的内容推送到CDN节点进行缓存，这样当终端用户首次访问该内容时，CDN节点已有缓存，无需回源，从而减少首次访问延迟。预热提交后会异步执行，各CDN节点的预热完成时间可能不同，不是瞬时完成的。预热与刷新是不同操作：预热是推送内容到节点，刷新是删除节点上的缓存内容。",ref:'help.aliyun.com/zh/cdn/'},
  {id:'cdn13',module:'内容分发CDN',type:'multi',question:"关于阿里云CDN日志，以下说法正确的有？",options:["CDN会自动记录用户访问日志，可通过控制台下载或投递到日志服务SLS","CDN日志中包含访问时间、客户端IP、请求URL、HTTP状态码等信息","CDN日志中的计费流量等于实际传输的数据量大小","CDN日志默认实时刷新，没有延迟"],answer:[0,1],explanation:"阿里云CDN自动记录所有用户访问日志，支持通过控制台下载日志文件，也支持将日志投递到日志服务SLS进行实时分析。日志中包含访问时间、客户端IP、请求方法、请求URL、HTTP状态码、响应大小等详细信息。CDN日志中的计费流量通常大于实际传输的数据量，因为还包括HTTP响应头等开销。CDN日志通常有一定延迟（最多24小时），非实时刷新。",ref:'help.aliyun.com/zh/cdn/'},
  {id:'cdn14',module:'内容分发CDN',type:'multi',question:"关于阿里云CDN的带宽封顶功能，以下说法正确的有？",options:["带宽封顶可以设置当CDN带宽达到阈值时自动触发告警或停用加速","设置带宽封顶可以有效控制CDN费用，避免异常流量导致费用突增","带宽封顶触发后，CDN加速服务会永久关闭，无法恢复","带宽封顶阈值可以按域名级别进行设置"],answer:[0,1,3],explanation:"CDN带宽封顶功能允许用户为加速域名设置带宽阈值，当域名的带宽使用量达到或超过设定阈值时，系统会自动触发告警通知或停止该域名的CDN加速服务，防止异常流量（如DDoS攻击或程序错误）导致CDN费用突增。带宽封顶按域名级别设置，触发停用后，用户可以在排查问题后手动恢复加速服务，不会永久关闭。",ref:'help.aliyun.com/zh/cdn/'},
  {id:'cdn15',module:'内容分发CDN',type:'multi',question:"阿里云CDN适用于以下哪些加速场景？",options:["网站静态资源（图片、CSS、JS）加速","大文件下载加速（如软件安装包、游戏客户端）","视频点播和直播流媒体加速","数据库实时同步和备份"],answer:[0,1,2],explanation:"阿里云CDN适用于多种内容分发加速场景：小文件静态加速（图片、CSS、JS等网页静态资源）、大文件下载加速（软件安装包、游戏更新包等）、视频流媒体加速（点播、直播）。数据库实时同步和备份不属于CDN的适用场景，应使用数据传输服务DTS或数据备份产品。",ref:'help.aliyun.com/zh/cdn/'},
  {id:'cdn16',module:'内容分发CDN',type:'multi',question:"关于阿里云CDN与OSS的联动配置，以下说法正确的有？",options:["CDN可以将OSS Bucket作为源站，利用OSS存储能力实现内容加速分发","当OSS Bucket为私有权限时，可通过配置CDN回源鉴权实现CDN节点安全回源OSS","CDN与OSS联动时，建议将OSS Bucket设置为公共读写权限以保证CDN正常回源","CDN与OSS联动时，OSS侧会产生回源流量费用，CDN侧产生CDN流量费用"],answer:[0,1,3],explanation:"CDN可以将OSS Bucket配置为源站，实现内容存储与加速分发的一体化方案。当OSS Bucket为私有权限时，可通过CDN控制台配置私有Bucket回源功能，CDN节点使用OSS的RAM角色或AccessKey进行回源鉴权，无需将Bucket设置为公共读写。CDN与OSS联动会产生两部分费用：CDN侧的加速流量费用和OSS侧的回源流量费用（从OSS到CDN节点的流量）。",ref:'help.aliyun.com/zh/cdn/'},
  {id:'cdn17',module:'内容分发CDN',type:'judge',question:"阿里云CDN支持IPv6访问，用户可以通过IPv6地址直接访问CDN加速域名获取内容。",options:["正确","错误"],answer:[0],explanation:"阿里云CDN已支持IPv6访问能力，CDN节点可以同时监听IPv4和IPv6请求。当客户端使用IPv6网络访问CDN加速域名时，CDN节点可以通过IPv6地址响应请求并返回缓存内容，帮助用户满足IPv6改造需求。",ref:'help.aliyun.com/zh/cdn/'},
  {id:'cdn18',module:'内容分发CDN',type:'judge',question:"阿里云CDN支持WebSocket协议，可以用于实时通信场景的内容加速。",options:["正确","错误"],answer:[0],explanation:"阿里云CDN支持WebSocket协议，WebSocket是一种在单个TCP连接上进行全双工通信的协议。CDN节点可以建立并保持WebSocket连接，适用于实时聊天、在线协作、实时数据推送等场景的加速。需要在CDN控制台的域名配置中开启WebSocket功能。",ref:'help.aliyun.com/zh/cdn/'},
  {id:'cdn19',module:'内容分发CDN',type:'judge',question:"阿里云CDN的加速区域仅支持\"中国大陆\"和\"全球\"两种选项，不支持仅加速海外（非中国大陆）区域。",options:["正确","错误"],answer:[1],explanation:"阿里云CDN的加速区域支持三种选项：中国内地（仅中国大陆加速）、全球（中国大陆和海外均加速）以及全球（不包含中国内地）（仅海外区域加速）。用户可以根据业务受众分布选择合适的加速区域，不同区域的计费标准也有所不同。",ref:'help.aliyun.com/zh/cdn/'},
  {id:'cdn20',module:'内容分发CDN',type:'judge',question:"在阿里云CDN中，可以配置对特定的HTTP状态码（如404）进行缓存，缓存后CDN节点会直接返回缓存的状态码响应，不再回源。",options:["正确","错误"],answer:[0],explanation:"阿里云CDN支持状态码缓存功能，用户可以配置对特定HTTP状态码（如404、403、500等）的缓存时间。当CDN节点收到源站返回的这些状态码时，会按照配置的缓存时间进行缓存。在缓存有效期内，客户端再次请求相同资源时，CDN节点直接返回缓存的状态码响应，不再回源。这可以减轻源站压力，例如缓存404可以防止恶意请求频繁回源。",ref:'help.aliyun.com/zh/cdn/'},
  {id:'gen01',module:'云计算通用',type:'single',question:"云计算的三种服务模型 IaaS、PaaS、SaaS 中，阿里云 ECS 属于哪一种？",options:["IaaS","PaaS","SaaS","DaaS"],answer:[0],explanation:"ECS 提供虚拟化的计算基础设施（服务器），用户自行管理操作系统及以上层，属于基础设施即服务（IaaS）。",ref:'help.aliyun.com/zh/ecs/'},
  {id:'gen02',module:'云计算通用',type:'multi',question:"以下关于 IaaS、PaaS、SaaS 的说法，正确的有哪些？",options:["IaaS 用户管理操作系统及以上","PaaS 用户管理应用程序和数据","SaaS 用户直接使用软件服务","IaaS 用户不需要管理任何基础设施"],answer:[0,1,2],explanation:"IaaS 用户管理 OS 及以上层，PaaS 用户管理应用和数据，SaaS 用户直接使用软件。IaaS 用户仍需管理基础设施中的 OS 层，\"不需要管理任何基础设施\"不正确。",ref:'help.aliyun.com/'},
  {id:'gen03',module:'云计算通用',type:'judge',question:"HTTP 协议默认使用 80 端口，HTTPS 默认使用 443 端口。",options:["正确","错误"],answer:[0],explanation:"HTTP 默认端口为 80，HTTPS 默认端口为 443，这是网络协议的标准约定。",ref:'help.aliyun.com/'},
  {id:'gen04',module:'云计算通用',type:'single',question:"以下哪项不属于云计算的核心特征？",options:["弹性伸缩，按需分配资源","按量计费，按使用量付费","资源池化，多租户共享底层资源","必须使用专用物理硬件，不支持虚拟化"],answer:[3],explanation:"云计算的核心特征包括：弹性伸缩（可根据业务需求自动或手动调整资源）、按量计费（按实际使用量付费）、资源池化（通过虚拟化技术将物理资源池化，多租户共享）、广泛的网络访问、可度量的服务等。必须使用专用物理硬件且不支持虚拟化完全相反，虚拟化是云计算的基础技术之一。",ref:'help.aliyun.com/zh/product/'},
  {id:'gen05',module:'云计算通用',type:'single',question:"关于公有云、私有云和混合云的描述，正确的是？",options:["公有云由企业自建自管，安全性最高","私有云由云服务商提供基础设施，多租户共享","混合云结合了公有云和私有云的优势，可将核心数据放私有云、弹性业务放公有云","混合云是指同时使用两个不同的公有云服务商"],answer:[2],explanation:"公有云由云服务商（如阿里云）建设和运营，多租户共享基础设施，成本较低、弹性好；私有云由企业自建或定制，资源专享，安全性高但成本较高；混合云结合两者优势，企业可以将核心数据和关键业务部署在私有云，将弹性扩展业务部署在公有云，通过专线或VPN连接，兼顾安全性和弹性。同时使用多个公有云通常称为多云（Multi-Cloud），而非混合云。",ref:'help.aliyun.com/zh/product/'},
  {id:'gen06',module:'云计算通用',type:'single',question:"关于KVM（Kernel-based Virtual Machine）虚拟化技术，以下说法正确的是？",options:["KVM是一种类型2（寄居式）虚拟机监控器，运行在操作系统之上","KVM是Linux内核模块，需要CPU支持硬件虚拟化（如Intel VT-x或AMD-V）","KVM只能运行Windows虚拟机，不支持Linux","KVM不支持热迁移功能"],answer:[1],explanation:"KVM是Linux内核中的虚拟化模块，将Linux内核转变为Hypervisor。KVM需要CPU硬件虚拟化支持（如Intel VT-x或AMD-V技术）。KVM支持运行多种操作系统的虚拟机，包括Linux和Windows。阿里云ECS的底层虚拟化技术也基于KVM等技术实现，支持热迁移等高级功能。",ref:'help.aliyun.com/zh/ecs/'},
  {id:'gen07',module:'云计算通用',type:'single',question:"关于容器与虚拟机的区别，以下说法正确的是？",options:["容器需要运行完整的操作系统内核，虚拟机不需要","容器共享宿主机内核，启动速度快，资源开销小","虚拟机的隔离性弱于容器","容器不能运行在虚拟机之上，两者互斥"],answer:[1],explanation:"容器和虚拟机的主要区别在于：虚拟机每个实例运行完整的操作系统（包括内核），隔离性强但启动慢、资源开销大；容器共享宿主机操作系统内核，通过命名空间和cgroups实现隔离，启动速度快（秒级），资源开销小。容器的隔离性弱于虚拟机（因为共享内核），但可以通过安全容器技术增强隔离。容器可以运行在虚拟机之上，两者并非互斥关系，实际生产中常在虚拟机上运行容器。",ref:'help.aliyun.com/zh/ecs/'},
  {id:'gen08',module:'云计算通用',type:'single',question:"关于阿里云地域（Region）和可用区（Available Zone）的关系，以下描述正确的是？",options:["一个地域只包含一个可用区","不同地域之间的ECS实例默认可以通过内网直接互通","不同可用区之间电力和网络相互独立，可用于构建高可用架构","可用区是阿里云全球数据中心的统称，不区分地域"],answer:[2],explanation:"地域（Region）是阿里云物理数据中心的地理区域（如华东1-杭州、华北2-北京），每个地域包含多个可用区。可用区（AZ）是同一地域内具有独立电力和网络设施的物理区域，不同可用区之间相互独立，可以利用多可用区部署实现高可用架构。一个地域通常包含多个可用区。不同地域之间的ECS实例默认不能通过内网互通，需要通过公网或云企业网CEN等方式连接。",ref:'help.aliyun.com/zh/ecs/'},
  {id:'gen09',module:'云计算通用',type:'single',question:"调用阿里云OpenAPI时，请求签名（Signature）的主要作用是？",options:["对传输数据进行加密，防止数据泄露","验证请求发送者身份和请求内容的完整性，防止篡改和伪造","压缩请求体，减少网络传输量","对请求进行负载均衡，分配到后端服务器"],answer:[1],explanation:"阿里云OpenAPI的请求签名机制使用AccessKey Secret对请求参数进行HMAC-SHA1计算生成签名。签名的主要作用是验证请求发送者身份（通过AccessKey ID标识用户）和请求内容的完整性（防止参数在传输过程中被篡改），而非加密数据内容。HTTPS协议负责传输层的数据加密。签名不涉及数据压缩或负载均衡。",ref:'help.aliyun.com/zh/sdk/'},
  {id:'gen10',module:'云计算通用',type:'single',question:"阿里云云监控（CloudMonitor）的自定义监控功能允许用户做什么？",options:["仅查看阿里云预置的ECS指标监控数据","用户自行上报业务指标数据，在云监控中查看和设置告警","监控其他云厂商的云服务资源","替代日志服务SLS进行日志采集和分析"],answer:[1],explanation:"云监控的自定义监控功能允许用户通过API或SDK将自定义的业务指标数据上报到云监控平台。用户可以定义指标名称、维度和数值，在控制台中查看监控图表、设置阈值告警和Dashboard展示。这弥补了云监控预置指标无法覆盖业务层面监控的不足。自定义监控不支持直接监控其他云厂商资源，也不替代SLS的日志采集功能。",ref:'help.aliyun.com/zh/cms/'},
  {id:'gen11',module:'云计算通用',type:'single',question:"阿里云标签（Tag）服务的核心用途不包括以下哪项？",options:["对云资源进行分类和分组管理","结合RAM策略实现基于标签的权限控制","通过标签筛选和统计资源，支持成本分摊","自动扩展ECS实例的计算性能"],answer:[3],explanation:"阿里云标签服务允许用户为云资源（如ECS、RDS、OSS等）添加键值对（Key-Value）标签，用于资源分类、分组管理、筛选统计和成本分摊。标签还可以与RAM策略结合，实现基于标签的精细化权限控制（如只允许操作带有特定标签的ECS实例）。标签不具备自动扩展ECS计算性能的功能，弹性伸缩由Auto Scaling服务实现。",ref:'help.aliyun.com/zh/tag/'},
  {id:'gen12',module:'云计算通用',type:'single',question:"关于阿里云资源编排服务ROS和Terraform的对比，以下说法正确的是？",options:["ROS是阿里云原生的IaC服务，Terraform是第三方工具，两者互不兼容","ROS和Terraform都需要在本地安装客户端才能管理云资源","ROS仅支持阿里云资源编排，Terraform支持多云资源编排","ROS不支持通过模板定义资源，只能通过控制台手动创建资源"],answer:[2],explanation:"ROS（Resource Orchestration Service）是阿里云原生的基础设施即代码（IaC）服务，通过JSON/YAML模板定义和管理阿里云资源，支持在控制台直接使用。Terraform是HashiCorp开源的多云IaC工具，通过HCL语言定义资源，支持包括阿里云在内的多家云平台。阿里云同时提供ROS和Terraform的支持，ROS支持通过模板自动化编排资源，两者并非互不兼容。",ref:'help.aliyun.com/zh/ros/'},
  {id:'gen13',module:'云计算通用',type:'multi',question:"在阿里云上构建高可用架构时，以下哪些做法是推荐的最佳实践？",options:["将应用部署在多个可用区，实现跨可用区容灾","使用负载均衡SLB分发流量到多台后端ECS实例","将数据库主备实例部署在同一台ECS上以节省成本","使用云监控设置关键指标的告警，及时发现问题"],answer:[0,1,3],explanation:"高可用架构的最佳实践包括：多可用区部署（将应用实例分布在不同可用区，单可用区故障不影响整体服务）；使用负载均衡分发流量并健康检查（自动剔除故障实例）；使用RDS等托管数据库的主备或集群架构而非自建单机数据库；配置云监控告警实现快速故障发现和响应。将数据库主备部署在同一台ECS上不满足高可用要求，单机故障会导致数据丢失和服务中断。",ref:'help.aliyun.com/zh/ecs/'},
  {id:'gen14',module:'云计算通用',type:'multi',question:"关于容灾指标RPO和RTO的描述，以下说法正确的有？",options:["RPO（恢复点目标）指允许丢失的最大数据量","RTO（恢复时间目标）指系统恢复服务所需的最长时间","RPO为0意味着不允许丢失任何数据，通常需要同步复制技术","RPO和RTO的值越大，容灾系统的成本越高"],answer:[0,1,2],explanation:"RPO（恢复点目标）指灾难发生后允许丢失的最大数据量，RTO（恢复时间目标）指系统从故障到恢复服务所需的最长时间。RPO为0表示不允许丢失任何数据，需要同步复制技术（如RDS主备同步）。RPO和RTO的值越小（而非越大），容灾要求越高，系统成本也越高。因此选项D说值越大成本越高是错误的。",ref:'help.aliyun.com/zh/ecs/'},
  {id:'gen15',module:'云计算通用',type:'multi',question:"关于阿里云负载均衡SLB（含CLB/ALB）的核心特性，以下说法正确的有？",options:["支持健康检查功能，自动移除不健康的后端服务器","支持会话保持，将同一客户端的请求转发到同一后端服务器","传统型CLB只支持四层（TCP或UDP）转发，不支持七层（HTTP或HTTPS）转发","支持多种调度算法，如轮询、最小连接数等"],answer:[0,1,3],explanation:"阿里云负载均衡支持健康检查（自动检测后端服务器状态，剔除故障实例）、会话保持（通过Cookie或Source IP保持会话）、多种调度算法（轮询RR、最小连接数LC、一致性哈希等）。传统型CLB（Classic Load Balancer）同时支持四层（TCP或UDP）和七层（HTTP或HTTPS）转发，选项C说只支持四层是错误的。ALB（Application Load Balancer）是七层专用负载均衡，提供更丰富的HTTP或HTTPS功能。",ref:'help.aliyun.com/zh/slb/'},
  {id:'gen16',module:'云计算通用',type:'multi',question:"典型的Web三层架构包括以下哪些层次？",options:["表现层（Web层或前端）","业务逻辑层（应用层或服务层）","数据访问层（数据库层或存储层）","网络安全层（防火墙层）"],answer:[0,1,2],explanation:"典型的Web三层架构包括：表现层（Web层，负责用户界面展示和请求接收，通常部署Web服务器如Nginx或Apache）、业务逻辑层（应用层，负责核心业务处理，通常部署应用服务器）、数据访问层（数据库层，负责数据存储和管理，如RDS或OSS）。网络安全层（防火墙）属于基础设施安全组件，不属于Web三层架构的分层范畴。",ref:'help.aliyun.com/zh/slb/'},
  {id:'gen17',module:'云计算通用',type:'judge',question:"在阿里云管理控制台中，用户可以将常用的云产品服务添加到收藏列表，方便快速访问。",options:["正确","错误"],answer:[0],explanation:"阿里云管理控制台提供了最近使用和收藏功能。控制台首页会自动记录用户最近访问的云产品服务，用户也可以手动收藏常用的云产品，将其固定在导航栏或首页快捷入口，方便快速定位和访问，提升操作效率。",ref:'help.aliyun.com/zh/'},
  {id:'gen18',module:'云计算通用',type:'judge',question:"CDN加速的实现依赖DNS解析，用户配置CDN加速后需要修改DNS解析记录，将域名CNAME指向CDN分配的CNAME地址。",options:["正确","错误"],answer:[0],explanation:"CDN加速的核心机制之一是通过DNS解析实现流量调度。用户在CDN控制台添加加速域名后，CDN会分配一个CNAME地址（如example.com.w.kunlunaq.com）。用户需要在域名DNS解析服务商处添加CNAME记录，将加速域名指向该CNAME地址。这样当用户访问域名时，DNS解析会将请求解析到CDN的智能调度系统，由调度系统分配最优的CDN节点为用户服务。",ref:'help.aliyun.com/zh/cdn/'},
  {id:'gen19',module:'云计算通用',type:'judge',question:"TCP协议是面向连接的可靠传输协议，通过三次握手建立连接；UDP是无连接的不可靠传输协议，不保证数据到达。",options:["正确","错误"],answer:[0],explanation:"TCP（传输控制协议）是面向连接的协议，在数据传输前通过三次握手建立连接，提供可靠传输（确认重传、流量控制、拥塞控制），适用于对数据完整性要求高的场景（如HTTP、文件传输）。UDP（用户数据报协议）是无连接的协议，不建立连接，不保证可靠传输，但开销小、延迟低，适用于实时性要求高的场景（如视频直播、DNS查询、在线游戏）。",ref:'help.aliyun.com/zh/'},
  {id:'gen20',module:'云计算通用',type:'judge',question:"阿里云SDK仅支持Java和Python两种编程语言，不支持其他语言。",options:["正确","错误"],answer:[1],explanation:"阿里云SDK支持多种编程语言，包括Java、Python、PHP、Node.js、Go、C#、C++、Ruby等主流编程语言。此外，阿里云还提供了CLI命令行工具和API Explorer等工具，方便不同技术栈的开发者调用阿里云OpenAPI。用户可以根据自身技术栈选择合适的SDK进行开发。",ref:'help.aliyun.com/zh/sdk/'},
];
